pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize creating small unusable gaps (1..9) as they are unlikely to fit future items.
    // Sweet spot is exactly 0 (perfect fit) or gaps large enough to accommodate common items (>20).
    let mut score = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        score -= 20.0;
    }

    // Heuristic: If we have many open bins, prioritize filling them to consolidate space.
    // If we have very few, be more conservative about creating "dead" space.
    score += (open_bins_count as f64) * 2.5;

    // Lookahead logic: If the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if (post_residual as u32) < next_item_size && (post_residual as u32) > 0 {
            score += 10.0;
        }
    }

    // Pressure to use existing bins:
    // Only open a new bin if the current fit is extremely poor or if we are late in the stream
    // and need to avoid fragmenting remaining capacity.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open a new bin
        } else {
            // Apply a heavy penalty for opening a new bin if existing bins are available
            score = 100.0 + (progress * 50.0);
        }
    }

    // Favor bins that align with the mean residual to keep bin fill-levels uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // Exponential growth for residuals < 15, as these are "dead zones".
    let fragmentation_penalty = if post < 15.0 {
        (15.0 - post).powf(2.5) * 5.0
    } else {
        0.0
    };

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // We penalize bins that would leave a post_residual too small for the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 10.0
    } else {
        0.0
    };

    // Dynamic thresholding: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to reduce open_bins_count.
    let closure_incentive = if progress > 0.8 {
        (open_bins_count as f64) * -2.0
    } else {
        0.0
    };

    // Base score is the residual space. We want to minimize this (Best Fit).
    // We add penalties to avoid "near-empty" bin states.
    let mut score = post + fragmentation_penalty + lookahead_penalty + closure_incentive;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the item barely fits in anything else.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low or 
        // the current item size is very large relative to open bin capacities.
        let new_bin_base_cost = 45.0; 
        score += new_bin_base_cost - (fitting_bins_count as f64 * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the returned score.
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items).
    // If post_residual is < 10, it's likely wasted space unless it's exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, favor keeping space.
    // If the next item cannot fit in this post_residual, we penalize the current choice slightly
    // to encourage keeping bins open that might accommodate larger items later.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive.
    let progress = step_index as f64 / total_items as f64;

    // 4. New Bin Handling:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fit quality is poor (high mean_residual)
        // or if we are nearing the end of the stream.
        let penalty = 25.0 + (mean_residual * 0.5) - (progress * 10.0);
        score += penalty;
    } else {
        // 5. Fitting Constraint: If this is the only bin that fits the current item, 
        // heavily reward selecting it (reducing score).
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 6. Global State: If we have many open bins, prioritize filling them (Best Fit).
        // If we have few open bins, we can afford to be more selective.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals
    // We want to minimize the post_residual to pack as tightly as possible.

    // 2. Lookahead logic (next_item_size):
    // If we have a next item, we want to leave enough room for it.
    // If post_residual is smaller than next_item_size, we effectively "waste" 
    // the potential of the next item fitting here.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 3. Penalty for opening a new bin prematurely:
    // If this is a new bin (bin_residual == bin_capacity), penalize based on 
    // how many other bins can already fit this item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64 * 40.0);
        // Penalize opening new bins when we have many open bins already
        score += (open_bins_count as f64 * 5.0);
    }

    // 4. Harmonic/Modulo influence:
    // Favor residuals that are multiples of common item sizes (20, 25)
    // to keep the bin state "clean" for future items.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 5.0;
    }

    // 5. Progression scaling:
    // As the stream nears completion, become more aggressive in packing
    // to avoid leaving too many bins under-utilized.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space (too small for most items)
    // We penalize residuals that are non-zero but below the typical item size (approx 30-40)
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals
    // If next_item_size is small, favor smaller post_residuals (Best Fit)
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // High penalty if next item won't fit here
            score += 40.0;
        } else {
            // Reward if next item fits perfectly or fills most of the space
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Heuristic for new bin: only open if the average residual is already high
    // or if the current bin fit is very poor (leaving very little space)
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin if we have plenty of open bins with good residuals
            score += mean_residual * 2.0;
        }
    }

    // Harmonic weighting: reward bins that are nearly full (residual near 0)
    // but avoid extreme fragmentation (post_residual < 5)
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 5 {
        score += 20.0;
    }

    // Phase-based adjustment: toward the end of the stream, be more aggressive
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) heavily using a quadratic term
    // The exponent 2.2 creates a non-linear "cliff" for very tight fits
    let fragmentation_penalty = (100.0 - post).powf(2.2);

    // Lookahead logic: if we have a next item, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize the bin because 
    // it creates a "dead zone" for the upcoming item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Global state awareness: 
    // As we approach the end of the stream (progress -> 1.0), 
    // we become more conservative about opening new bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // If we have many open bins, opening a new one is expensive.
        // If we are near the end, opening a new one is very expensive.
        (open_bins_count as f64 * 5.0) + (progress * 50.0)
    } else {
        0.0
    };

    // Interaction between mean_residual and current post_residual
    // Favors bins that keep the overall average residual balanced.
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Final score: lower is better. 
    // We want to minimize the post_residual (Best Fit) but avoid the fragmentation cliff.
    let mut score = post + fragmentation_penalty + lookahead_penalty + new_bin_penalty + balance_factor;

    // If this is the only bin that fits, give it a significant priority boost
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening new bins, but reduce penalty as we approach the end of the stream
        // to ensure we don't leave many partially filled bins.
        score = 45.0 - (progress * 15.0);
    } else {
        // Reward placements that leave a residual smaller than the next item if possible (Best Fit variant)
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 25.0; // Penalize "wasting" space that could have fit the next item
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.1;
            }
        }

        // Avoid creating "dead" space (residuals too small for any item)
        // Since we don't know the min item size, we assume 10 is a common lower bound
        if post_residual < 10 && post_residual > 0 {
            score += 30.0;
        }

        // Global pressure: If we have many bins open, prioritize filling the ones with least residual
        // to consolidate space.
        score += (bin_residual as f64 - mean_residual) * 0.5;

        // If this is the last chance to fit into an existing bin, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining capacity.
    // We want to minimize post_residual (Best Fit), but with non-linear penalties.
    let mut score = post;

    // Penalty for creating small, unusable gaps (1-9 range is often "dead space").
    // We apply a non-linear penalty to post_residuals that are small but not zero.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 2.0;
    }

    // Interaction with the lookahead:
    // If the next item cannot fit into the current post_residual, we penalize this bin
    // more heavily as we approach the end of the stream.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * (1.0 + progress * 2.0);
    }

    // If this is a new bin, we only want to open it if the current open bins are 
    // "poor" fits. We compare the new bin's cost (100 - item_size) against 
    // the mean residual of existing bins.
    if is_new_bin {
        let new_bin_cost = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin if the mean_residual is already tight,
        // but reward it if we are early in the stream or if existing bins are fragmented.
        score = new_bin_cost + (mean_residual * 0.5) + (progress * 10.0);
    } else {
        // Encourage filling bins that are already partially full (Best Fit strategy).
        // The more bins open, the more we want to consolidate (penalize extra bins).
        score += (open_bins_count as f64).powf(1.2);

        // If this is the last chance for this item, reduce penalty to ensure it fits.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common small-to-mid items (10-30).
    // This acts as a "fragmentation" repellent.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead Synergy: If the next item can fit into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    }

    // 3. New Bin Thresholding: If we are forced to pick a new bin (fitting_bins_count == 0),
    // we normalize its score to prevent it from being unfairly penalized.
    if bin_residual == bin_capacity {
        // Evaluate the cost of opening a new bin vs the mean state of current bins.
        score = 25.0 + (mean_residual * 0.5);
    } else {
        // 4. Harmonic Density: Favor bins that leave a residual which is a multiple of 10 or 25,
        // as these are statistically more likely to accommodate future items in a 100-capacity system.
        let mod_val = post_residual % 25;
        if mod_val == 0 {
            score -= 15.0;
        } else if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive about filling
    // remaining space to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    // 6. If this is the last chance for the current item, reduce the score significantly
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (near-empty space is bad)
    // We prioritize bins where the post_residual is small, but not too small to lose flexibility.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Matching: Reward bins where the post_residual can perfectly or 
    // nearly accommodate the next item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit or near-exact fit for next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 1.5;
        } else {
            // Penalize if the next item won't fit in this bin anymore
            score += 25.0;
        }
    }

    // 3. Mean Residual Balancing: Penalize bins that deviate significantly from the 
    // average efficiency of open bins to keep bin states synchronized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fit is objectively poor (e.g., leaving a large, unusable gap).
    if bin_residual == bin_capacity {
        // This is a new bin. Only pick if existing bins have very poor fits.
        // We set a threshold based on the average residual.
        score = mean_residual * 0.8;
    } else {
        // If this is the only bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive 
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize creating small, unusable gaps (1..9).
    // Small gaps are "dead" space that rarely fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, be more conservative
    // about opening new bins. 
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        score += 25.0 + (progress * 50.0);

        // If we are early in the stream, favor opening a new bin if the mean residual
        // of existing bins is already quite low.
        if progress < 0.3 && mean_residual < 20.0 {
            score -= 15.0;
        }
    } else {
        // 4. Global State Awareness: If we have many open bins, penalize non-optimal
        // fits to force consolidation.
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 0.5;
        }
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item,
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize remaining space (Best Fit)
    // Reward lower post_residual values.
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is too small to fit 
    // the next item, penalize it quadratically, weighted by stream progress.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res).powf(1.5) * (1.0 + progress);
    }

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate the "cost" 
    // of opening it. We only open if the current fitting bins offer a very poor fit.
    if bin_residual == bin_capacity {
        // High penalty to prevent premature new bin opening.
        // Penalty decreases as the number of available fitting bins decreases.
        score = 45.0 + (55.0 / (fitting_bins_count as f64 + 1.0)) + (progress * 20.0);
    } else {
        // Favor bins that align with the mean residual to keep bins balanced.
        // This prevents the "fragmentation" of having many bins with widely different residuals.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;

        // Penalize bins that become "too tight" if we are early in the stream,
        // but allow them late in the stream to maximize packing density.
        if post_residual < 10 {
            score += (10.0 - post_res) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Prioritize Best-Fit (smaller post_residual is better).
    // 2. Penalize opening new bins unless current bin choices are extremely poor.
    // 3. Use lookahead to avoid leaving gaps that cannot fit the next item.
    // 4. Incorporate global state to balance packing density against bin count.

    let mut score = post_residual as f64;

    // Penalty for creating a bin that is "too empty" (fragmentation)
