    // New bin logic:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only open a new bin if the current packing is inefficient or we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Base cost for opening a new bin is high, but decreases as we reach the end of the stream (to clear remaining items)
        score = 45.0 - (progress * 15.0);

        // If we have few open bins and many items left, don't open a new one easily
        if open_bins_count < 2 && progress < 0.8 {
