    } else { 
        0.0 
    };

    // Reward bins that leave very little space (Perfect fit bonus)
    // We use an exponential decay on the post_residual to favor tight fits
    let tight_fit_reward = -(100.0 / (1.0 + post));

    // Lookahead coupling: if the next item is large, favor bins that leave enough space
    // to accommodate it, otherwise favor filling the bin completely.
    let lookahead_factor = if next_item_size > 0 {
