    // 3. Mean Residual Balancing: Avoid creating bins that are significantly worse than the 
    // average residual of currently open bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. New Bin Thresholding: If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only open a new bin if the current fit quality (post_residual) is poor relative 
    // to the total number of bins already in play.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high to encourage packing.
        score = 45.0 + (open_bins_count as f64 * 0.1);

        // If we are near the end of the stream, prioritize closing existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
