    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), we set a high baseline cost.
    // We lower this cost as we progress through the stream to allow for more 
    // bin openings as the packing density needs to be sacrificed for efficiency.
    let new_bin_cost = if bin_residual == bin_capacity {
        40.0 - (20.0 * progress)
    } else {
        0.0
    };

    // Penalize fragmentation when many bins are open.
    let fragmentation_penalty = open_bins_count as f64 * 0.1;

    post + dead_space_penalty + flexibility_reward + lookahead_penalty + new_bin_cost + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is small (1-9), it often traps space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual,
    // strongly incentivize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest one.
    // Otherwise, prioritize keeping the mean residual high to accommodate future large items.
    if open_bins_count > 0 {
        let residual_ratio = post_residual as f64 / mean_residual;
        score += residual_ratio * 5.0;
    }

    // 4. Threshold for New Bin: If this is a new bin (bin_residual == bin_capacity),
    // penalize based on the item_size relative to capacity to avoid wasting a new bin on small items.
    if bin_residual == bin_capacity {
        score += (item_size as f64 * 0.4) + (open_bins_count as f64 * 2.0);

        // If there are other bins that could fit the item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, favor tighter fits (Best Fit)
    // to minimize the number of bins left open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
