        // promoting uniform packing across all open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= 5.0 * (1.0 / (1.0 + deviation));
    }

    // Scale by open_bins_count to discourage excessive parallel bin usage.
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
