    // If the current bin is "drier" than the average, it's a good candidate to fill.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, it's often 
    // impossible to fit future items (min size 1). We penalize small residuals 
    // that are not zero, favoring exact fits.
    if post_res > 0.0 && post_res < 10.0 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item is large, avoid bins that leave very little space
    // that cannot accommodate the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: As we reach the end of the stream, prioritize closing bins
    // (fitting into existing bins) over opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin increasingly as we progress through the stream.
        score += 40.0 * progress;

        // If there are bins that can fit the item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // If this is the last chance for this item to fit, reward it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Influence of open bins: penalize creating too many fragmented bins early on.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Penalize large post_residuals to favor tight packing
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: If post_residual is small, it might be unusable for future items.
    // If post_residual < 10 (minimum item size), it is 'dead space'.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic: If next_item_size exists, penalize bins that can't fit it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0; // Reward bins that can accommodate the next item
    }

    // 4. Entropy Management: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong disincentive to open a new bin if space exists
        } else {
            score -= 20.0; // Normalize for the necessary case
        }
    }

    // 5. Mean residual coupling: If the bin is much fuller than the average bin, 
    // it is a high-quality bin; reward it to keep it "hot".
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 5.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    // prioritize tighter packing to minimize straggler bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

