    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let bin_res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Penalty for opening a new bin (bin_residual == cap)
    // We scale this penalty to be higher when we have plenty of open bins
    let open_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 5.0) + (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // Calculate "Best Fit" pressure: prioritize bins that leave the least remaining space,
    // but modulate this based on the lookahead (next_item_size).
    // If post_residual is close to next_item_size, we reward it to avoid fragmentation.
    let fit_efficiency = if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        diff * 0.5
    } else {
        post_res * 0.1
    };

    // Penalize creating "dead space" (small residuals that cannot fit common items)
    // We define dead space as residuals < 10.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Interaction term: If we are near the end of the stream, prioritize closing bins
    // by being more aggressive with the Best Fit (lower post_residual).
    let progress_scaling = 1.0 + (progress * 2.0);

    let score = (post_res * 0.8) + (fit_efficiency * progress_scaling) + dead_space_penalty + open_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

