    // 2. Harmonic penalty: penalize residuals that are not multiples of common item sizes (e.g., 20, 25, 33)
    // to keep bins "compactable" for future arrivals.
    let residual_harmonic_penalty = (post_residual % 20) as f64 * 1.5;
