            // Reward if the bin can accommodate the next item perfectly
            score -= 10.0;
        }
    }

    // 3. Efficiency coupling: favor bins that remain close to the mean residual of the set
    // This maintains a balanced distribution of space across all bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Finality check: if this is the last item, prioritize the smallest residual (Best Fit)
    if next_item_size == 0 {
        score = post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize bins that leave the smallest residual.
    // The base score is post_residual, which inherently favors tight fits.

    // 2. Penalty for creating "orphaned" space:
    // If the post_residual is small but large enough to be unusable (e.g., < 10), it is often worse 
    // than a slightly larger residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead awareness:
    // If the next item cannot fit into the current bin's post_residual, that space is effectively wasted 
    // for the immediate future. If it can fit, we reward the bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // 4. Global state pressure:
    // If we have many open bins, we should be more aggressive about filling existing ones 
    // rather than opening new ones (penalty for new bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 2.5;

        // Penalize opening a new bin if an existing bin could have taken the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Dynamic time horizon:
    // As we approach the end of the stream, prioritize closing bins (reducing open_bins_count).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // If we are near the end, prioritize fitting into existing bins to consolidate.
        if !is_new_bin {
            score -= 10.0;
        }
    }

    // 6. Mean residual balancing:
    // Avoid creating bins that are significantly below the current average density.
    if !is_new_bin && (post_residual as f64) < (mean_residual * 0.5) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening new bins: scale by progress to be more conservative as the stream ends
    if is_new_bin {
        score += 15.0 + (progress * 25.0);
    } else {
        // Reward tight fits that leave little room for future items
        // We want to minimize post_residual, but prioritize bins that become "tight"
        // based on the lookahead next_item_size.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score -= (100.0 - post_residual as f64) * 0.1;
            } else {
