    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (1.0 - progress * 0.5);
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new one unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Dynamic balancing: penalize high mean_residual to keep bins tightly packed on average
    score += (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

