        // This encourages filling existing bins rather than spreading items thin.
        score -= (100.0 - bin_residual as f64) * 0.1;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item,
    // reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual as the base penalty (Best-Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (gaps smaller than the smallest likely item).
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
