    }

    // 2. Lookahead matching: If next_item_size fits perfectly into the remaining space, 
    // strongly reward this bin (Best-Fit-Lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (50.0 - diff).max(0.0);
