    // fitting options are extremely poor (high post_residual for all).
    if bin_residual == bin_capacity {
        score += 45.0; // Base cost to open a new bin
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 15.0;
        }
    }

    // 4. Density Balancing: If the current bin's residual is much higher than the mean,
    // prioritize filling it to bring it closer to the average utilization.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Progression awareness: As the stream nears the end, become more aggressive 
    // about closing bins (minimizing total bins used).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
