    // 2. Harmonic penalty for small residuals (dead space creation)
    // We heavily penalize post_residuals that are too small to fit common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Pressure: If this is the only bin that can take the item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. Threshold against opening new bins:
    // If we are looking at a new bin (bin_residual == bin_capacity), apply a penalty
    // proportional to the current number of bins to encourage filling existing ones.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Harmonic refinement: Use the mean residual of existing bins to favor packing
    // into bins that are already "less full" (higher residual) to keep them flexible.
    if bin_residual < bin_capacity {
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    // 7. Progression scaling: As we approach the end of the stream, prioritize efficiency over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
