    // Incorporate mean_residual to balance load across bins (avoid creating one very full bin 
    // and many empty ones, which wastes capacity for large items).
    let load_balancing = (post - mean_residual).abs() * 0.5;

    let mut score = tightness_reward + fragmentation_penalty + lookahead_bonus + new_bin_penalty + load_balancing;

