    // Heuristic: If we are near the end of the stream, prioritize aggressive filling (smaller residuals)
    // If early in the stream, favor keeping bins slightly emptier to accommodate larger future items
    let capacity_pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
    score += capacity_pressure * 20.0;

    // If this is a new bin, apply a structural penalty that scales with the number of open bins
    // This discourages opening new bins unless the existing ones are truly poor fits
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Lookahead incentive: If the next item fits better in this current bin's post_residual,
        // reward the placement to reduce fragmentation
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= (next_item_size as f64 * 0.5);
        }

        // If this is the last bin that can fit the current item, lower the score to prevent
        // forcing a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Normalize against mean_residual to avoid clustering bins with widely different fill levels
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We prioritize bins that result in smaller residuals.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward configurations that leave room for specific item-size classes
    // If post_residual is small but unusable, it's "dead space". 
    // We penalize residuals that are too small to fit common item ranges (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; 
    }

    // 3. Lookahead Integration: 
    // If next_item_size is known, favor bins where the remaining space (post_residual) 
    // is just enough to fit the next item (tight packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - fit_diff) * 0.2;
        } else {
            // Penalize if this bin will definitely not fit the next item 
            // when other bins might have.
            score += 15.0;
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive
    // unless fitting_bins_count is very low, suggesting we are forced to open one.
    if bin_residual == bin_capacity {
        score += 60.0;
        score -= (fitting_bins_count as f64) * 5.0;
    }

    // 5. Global Balance:
    // Penalize opening too many bins relative to the mean residual of current bins.
    // If the mean residual is high, we have plenty of "slack", so don't open new bins.
    score += (open_bins_count as f64) * 2.0;
    score -= mean_residual * 0.1;

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
