    // 2. Lookahead Coupling: If next_item_size exists, favor bins that leave exactly enough
    // space for the next item (perfect fit) or maximize remaining space for future items.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // Perfect harmonic alignment
        } else if post_residual < next_item_size {
            score += 30.0; // Penalize blocking the next item
        }
    }

    // 3. Global Density Management: As the stream progresses, prioritize closing bins
    // that are already significantly emptier than the global mean.
    let density_factor = (bin_residual as f64 - mean_residual).abs();
    score += density_factor * 0.5;

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Only choose if existing options are terrible.
        if fitting_bins_count > 0 {
            score += 45.0; // Strong penalty for opening new bin if others exist
        }
    }

    // 5. Harmonic Class Logic: Use modulo of capacity to favor bins that reach 
    // specific thresholds (e.g., leaving a remainder of 0, 25, 50).
    let harmonic_mod = post_residual % 25;
    if harmonic_mod == 0 && post_residual > 0 {
