    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global Load Balancing: If the bin is emptier than the mean, prefer filling it
    // to consolidate items and reduce the number of active bins.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Thresholding: Prevent opening a new bin unless the current options are terrible.
    // If this is a new bin, apply a significant penalty based on the current packing density.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Last-Chance Logic: If this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the number of bins available.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we heavily reward this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 5.0;
        // Further encourage tight fits for the lookahead pair
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the current 
    // fit is extremely poor (large post_residual) or we are late in the stream.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 85.0;
        // Reduce penalty if we have many open bins already to prevent fragmentation
        score -= (open_bins_count as f64) * 2.0;
        // Increase penalty as we approach the end of the stream
        score += progress * 40.0;
    }

    // 4. Global State Balancing: If we have very few fitting bins, we must be careful 
    // not to waste the last few "good" spaces.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; // Prioritize using the last remaining "good" bin
    }

    // 5. Mean Residual Correction: Avoid creating bins that are significantly 
    // worse than the current average performance of the system.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity)
    // proportional to the progress, making it harder to open new bins as the stream nears the end.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (50.0 * progress));

    // Best-Fit Decreasing logic: penalize large post_residual (wasted space)
    // but modulate this based on the number of fitting bins (if only 1 bin fits, we are forced to take it).
    let fitness_penalty = post * (1.0 + (1.0 / (fitting_bins_count as f64 + 1.0)));

    // Lookahead: If the next item exists, penalize placements that leave too little space for it.
    // We want to avoid leaving residual space slightly smaller than the next item if possible.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        25.0 * (1.0 - (post_residual as f64 / next_item_size as f64))
    } else {
        0.0
    };

    // Interaction term: penalize high fragmentation relative to the global mean residual
    // to keep bins tightly packed similarly to one another.
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    let score = fitness_penalty + new_bin_penalty + lookahead_penalty + fragmentation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) core: reward small post_residual.
    // However, we penalize "fragmentation" where post_residual is too small to fit common items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Harmonic Class Logic: Lookahead integration.
    // If next_item_size fits in the post_residual, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further favor bins that result in a "clean" finish (near-zero residual)
        if post_residual == next_item_size {
