    // 3. Pressure management: If this is the last fitting bin, avoid it if the fit is very poor.
    // Penalize opening a new bin unless the current fit is catastrophic (> 50% waste).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0; // Discourage opening new bins if others exist
        } else {
            score -= 10.0; // Neutral baseline for mandatory new bin
        }
    }

    // 4. Density Balancing: If open_bins_count is high, prioritize filling existing bins
    // to keep the distribution tight.
    score += (open_bins_count as f64) * 0.5;

    // 5. Modulo-based "Shelf" heuristic:
    // Items that fit perfectly into 100/N slots are preferred.
    let fit_ratio = (bin_capacity - post_residual) % 25;
    if fit_ratio == 0 {
        score -= 5.0;
    }

    // 6. Temporal decay: As we approach the end of the stream, prioritize tight packing
    // more aggressively to avoid trailing leftovers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
