    if next_item_size > 0 && (post_residual < next_item_size) {
        score += 15.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // lower the score to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Mean residual alignment: Favor bins that stay near the mean to keep bins balanced.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: reward smaller post_residual (tighter packing)
    // We already have post_residual as base score.

    // 2. Lookahead Coupling:
    // If next_item_size fits in the post_residual, drastically reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Penalty:
    // If post_residual is small but > 0, it often becomes 'dead space'.
    // Penalize post_residuals that are too small to fit common items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // proportional to the number of existing bins to discourage fragmenting space.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Last Chance Logic:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 7. Progress Weighting:
    // As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins where the post-residual is small (tight packing).
    // The base score is post_residual.

    // 2. Penalty for creating "stranded" space: If post_residual is small but > 0, 
    // it creates a gap that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage pairing items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global state management: If we are near the end of the stream, 
    // be more aggressive about closing bins (higher penalty for opening new ones).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if an existing one can take it
            score += 60.0 * (1.0 + progress);
        } else {
            // Must open a new bin
            score = 0.0;
        }
    }

    // 5. Dynamic thresholding: If the mean residual of current bins is high, 
    // we want to fill those bins rather than starting new ones.
    if mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // 6. Avoid "Last Chance" traps: If this is the only bin that fits the item,
    // give it a slight preference boost to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (lower post_residual)
    let mut score = post_res;

    // Penalty for creating "orphaned" gaps: if the post_residual is small but not zero,
    // it often creates unusable space. We penalize small residuals more heavily as the 
    // stream progresses, assuming we want to finish bins cleanly toward the end.
    if post_res > 0.0 && post_res < 15.0 {
        score += (15.0 - post_res) * (1.0 + progress * 2.0);
    }

    // Lookahead interaction: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 0.8;
        }
    }

    // Dynamic pressure: If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    // If we have few open bins, we are more flexible.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) * (1.0 - progress * 0.5);
    }

    // Interaction with mean_residual: If current bin is significantly "fuller" than the average
    // open bin, reward it to consolidate space.
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Final adjustment: Penalize creating a new bin if other fitting bins exist (fitting_bins_count > 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a structural penalty based on current efficiency
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already tight (< 15)
        // or if we have no other choice (fitting_bins_count == 0).
        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 150.0;
        } else {
            score += 45.0; // Base cost to open a new bin
        }
    } else {
        // 2. Best-Fit Decreasing logic: Favor bins that leave very little space
        // Penalize large post_residuals (the "dead space" penalty)
        score += (post_residual as f64).powf(1.2);

        // 3. Lookahead logic: If a future item exists, prioritize bins that can accommodate it
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 25.0; // Reward bins that can fit the next item
            } else {
                // Penalize if this placement makes the next item impossible to fit
                score += 10.0;
            }
        }

        // 4. Harmonic class pressure: 
        // If the post_residual is a small fraction of capacity, it's often "wasted"
        // unless it's near zero.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; 
        }

        // 5. Progression awareness: 
        // As we reach the end of the stream, prioritize closing bins over opening new ones
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score -= (1.0 - progress) * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" gaps (dead space < 10, as items are >= 10)
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Pressure mechanism: discourage opening new bins unless necessary
    // If this is a new bin, apply a penalty scaled by the number of currently open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead optimization (Best Fit / Next Fit hybrid)
    // If we have a next item, check if it fits in the current post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 15.0;
        } else if post_residual < 10 {
            // Further penalize if we leave a gap that cannot fit the next item AND no future item
            score += 20.0;
        }
    }

    // 4. Global state optimization
    // Favor bins that keep the mean_residual high (balanced filling)
    // Avoid leaving bins with very little space if other bins have much more space
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // 5. Last chance protection
    // If this is the only bin that fits, we MUST prioritize it (low score)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
