    // 3. Efficiency Balancing: Use mean_residual to avoid fracturing bins.
    // If the current bin's post_residual is significantly worse than the average, penalize.
    if (post_residual as f64) > mean_residual {
        score += 15.0;
    }

    // 4. New Bin Thresholding: Prevent opening new bins unless necessary.
    // If this is a new bin (residual == capacity), add a high penalty unless it's the only option.
    if bin_residual == bin_capacity {
