    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit into the current post_residual,
    // we reward this placement to keep the bin useful for the immediate future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Open Bin Pressure: If we have many bins open, we penalize opening a new bin (bin_residual == bin_capacity).
    // We favor packing into existing bins to minimize the total count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the current item, 
    // it is a high-priority candidate regardless of local fit quality.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: Penalize bins that deviate significantly from the mean_residual
    // to keep the bin distribution uniform and prevent "starved" bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
