            score += 20.0;
        }
    } else if fitting_bins_count == 1 {
        // High priority to use the "last chance" bin to keep it from becoming stranded
        score -= 20.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
