    // 1. Harmonic Penalty: Penalize post_residual based on "dead zone" vulnerability.
    // If post_residual is small (e.g., < 10), it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.5;
    }

    // 3. New Bin Threshold: Discourage opening new bins unless the current fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty to open a new bin if other bins are available and efficient.
        score += 45.0 + (open_bins_count as f64 * 2.0);

        // If we are at the end of the stream, relax the new bin penalty.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;
    }

    // 4. Harmonic Alignment: Bias towards values that are multiples of 10 or 20,
    // as these are common item sizes in many distributions.
    let alignment_penalty = (post_residual % 10) as f64;
    score += alignment_penalty * 0.8;

    // 5. Fitting Pressure: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 6. Global Efficiency: Penalize bins that deviate significantly from the mean residual.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
