pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize the new bin candidate (where residual == capacity) significantly 
    // unless the fit is extremely poor in existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 45.0 + (progress * 20.0) } else { 0.0 };

    // Best Fit Decreasing logic: reward smaller post_residual (tighter fit).
    // We use a quadratic term to heavily penalize large gaps (dead space).
    let fit_score = post * post / 100.0;

    // Lookahead logic: If we have a next item, check if it fits in the current post_residual.
    // If it does, we reward this bin to encourage packing two items together.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for creating "fragmented" bins: 
    // If the post_residual is small but not zero, it might be useless (e.g., < 10).
    // We penalize very small residuals that are likely to be wasted.
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Scaling factor based on number of bins to encourage consolidation.
    let scale = 1.0 + (open_bins_count as f64 * 0.05);

    (fit_score + lookahead_bonus + fragmentation_penalty + new_bin_penalty) * scale
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

