    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (30.0 - diff).max(0.0);
    }

    // 3. Balance usage: If fitting_bins_count is low, we are running out of options; prioritize tight fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // 4. Global distribution awareness: Penalize bins that drift significantly from the current mean_residual.
    let drift = (post_residual as f64 - mean_residual).abs();
    score += drift * 0.2;

    // 5. New bin management: If bin_residual == bin_capacity, it is a new bin.
    // Only open a new bin if the penalty for using existing bins is prohibitively high.
    if bin_residual == bin_capacity {
        // High base cost for opening new bins, reduced slightly as we reach the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 60.0 - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalize opening new bins, but reduce penalty as we approach the end of the stream
        // to ensure we don't leave many partially filled bins.
        score = 45.0 - (progress * 15.0);
    } else {
        // Reward placements that leave a residual smaller than the next item if possible (Best Fit variant)
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 25.0; // Penalize "wasting" space that could have fit the next item
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.1;
            }
