        // Avoid creating "dead" space (residuals too small for any item)
        // Since we don't know the min item size, we assume 10 is a common lower bound
        if post_residual < 10 && post_residual > 0 {
            score += 30.0;
        }

        // Global pressure: If we have many bins open, prioritize filling the ones with least residual
        // to consolidate space.
        score += (bin_residual as f64 - mean_residual) * 0.5;

        // If this is the last chance to fit into an existing bin, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
