}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "wastage" while balancing bin consolidation vs. flexibility.
    // post_residual represents the "waste" if we choose this bin.
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin if other options exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0; 
    }

    // 2. Harmonic Class Logic: Reward placements that leave post_residual in "high-utility" zones.
    // Smaller residues are generally better, but residues that are multiples of common item sizes (e.g., 20, 25)
    // are more likely to be filled by future items.
    if post_residual > 0 {
        let remainder = post_residual % 20;
        if remainder == 0 {
            score -= 5.0; // Reward alignment with common factors
        }
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Density Balancing: If the bin is becoming very empty, penalize it to force consolidation.
    // If post_residual is high, we are leaving too much space.
    if post_residual > 60 {
        score += 15.0;
    }

    // 5. Urgency: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should be more willing to accept a slightly worse residual to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Stage Progression: As we near the end of the stream, prioritize tight packing (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
