    // expected items (e.g., < 10), it becomes "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty proportional 
    // to the count of already open bins to favor filling existing ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Optimization: If a next item exists, penalize placements that
    // make the next item harder to place in this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot fit the next item if it could have.
            score += 25.0;
        } else {
            // Reward keeping space for the next item (Best Fit approach).
            score -= (100.0 - post_residual as f64) * 0.2;
        }
    }

    // 4. Tightness Reward: Favor bins that are near capacity after placement 
    // to maximize bin utilization, but prevent "last chance" bins from being ignored.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // better than the mean, reward the selection.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": residuals smaller than the smallest likely item (10)
    // unless it is an exact fit (0 residual).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // Reward bins that can accommodate the next item perfectly or near-perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_diff = (post_residual - next_item_size) as f64;
            // Reward if the next item fits well in this bin
            score -= 30.0 * (1.0 - (fit_diff / 100.0));
        } else {
            // Penalize if the next item definitely won't fit
            score += 15.0;
        }
    }

    // 3. Balance against mean_residual:
    // If the current bin is significantly emptier than the average, prioritize filling it
    // to keep the overall bin count low.
    if bin_residual as f64 > mean_residual {
        score -= 20.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // 4. Force efficiency when bins are scarce:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Logic:
    // Heavily penalize opening a new bin unless it's the only option or the current 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if existing bins are very poor fits
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: higher when many bins are already open,
        // or when we are near the end of the stream.
        score += 45.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0);
    } else {
        // Best-Fit Decreasing behavior: prefer bins with smaller post_residual
        // Penalize bins that leave very small, unusable slivers (e.g., 1-5 units)
        if post_residual > 0 && post_residual < 6 {
            score += 25.0;
        }

        // Lookahead: if the next item fits into this bin's post_residual, prioritize this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Adaptive balancing: if the bin's post_residual is significantly better than the global mean,
        // reward it to keep the "good" bins tighter.
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid wasting space elsewhere
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity (Best Fit principle).
    // Penalize smaller residuals (tight fit) less as the stream progresses to consolidate space.
    let mut score = post_res * (1.0 + 0.5 * progress);

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting later. 
    // We heavily penalize residuals between 1 and 15 (unusable slivers).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next_item_size is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next_item_size, we penalize the choice.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - progress);
    }

    // New Bin Logic: Only open a new bin if the current fit is extremely poor.
    // If this is the "new bin" candidate (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // High base cost to open a new bin, but reduce as we near the end of the stream
        // to avoid being stuck with a single large item in a new bin.
        score = 45.0 - (20.0 * progress);

        // If we have many open bins, penalize opening another one.
        score += open_bins_count as f64 * 2.0;
    }

    // Encourage filling bins that are already "near full" (low mean_residual) 
    // to keep the number of active bins minimal.
    score += (mean_residual - post_res) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a small, unusable gap (fragmentation)
    // We penalize residuals that are too small to fit the smallest common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Harmonic preference: Reward residuals that are perfect multiples of the next item
    // or leave space for a "round" remainder (e.g., leaving exactly 50 or 25)
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        score += (remainder as f64) * 0.5;

        // If next_item fits perfectly, heavily reward this bin
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Logic for new bin vs. existing:
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fit is terrible
        // in all existing bins.
        score += (open_bins_count as f64) * 2.5;

        // If we are near the end of the stream, discourage opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    } else {
        // Favor bins that have a residual close to the mean, maintaining balance
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Critical constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: Heavily penalize small, unusable gaps (1..9 range)
    // which are likely to become permanent "dead zones" in the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item_size is known, favor bins that can 
    // accommodate it specifically after placing the current item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bin pressure: Penalize opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity), increase score
    // proportionally to the number of open bins that could have taken the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + (fitting_bins_count as f64 * 5.0);
    }

    // 4. Compactness bias: Favor bins that are already closer to being "full"
    // (low bin_residual) to keep the number of active bins minimal.
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Progression adjustment: As the stream nears completion, become more 
    // aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (Minimize post_residual)
    // We start with post_residual as the score.

    // 2. Penalty for creating "orphan" space (dead space that is unlikely to hold future items)
    // If post_residual is small but > 0, it's often better to leave it large than to create a sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter alignment with the next item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Mean Residual Balancing: Avoid deviating too far from the average state of other bins.
    // This keeps the "fill" levels consistent across the bin set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. New Bin Logic: Discourage opening a new bin unless the current fill quality is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin. 
        // We only open a new bin if the current options are all worse than ~30.0.
        score += 35.0;

        // If we are late in the game, opening a new bin is increasingly expensive.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Urgency: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
