    let mut score = post_res + (post_res.powf(1.5) * progress);

    // Lookahead logic: If the next item fits into the current post_residual, 
    // heavily reward this bin to create a "perfect" pair.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating the "New Bin" option.
    // Increase the cost of new bins as the stream progresses to force packing 
    // into existing space.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // Fitting Bins constraint:
    // If this is the only bin that can fit the item, lower the score to 
    // ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalty for creating bins with very small, unusable residuals (< 10) 
    // unless the bin is exactly full (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Couple with mean_residual:
    // If this bin's post_residual is significantly worse than the average, penalize.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
