    // We favor bins that leave the least space (smaller post_residual).
    // Adding a small bias based on fitting_bins_count to prioritize using existing bins
    // over opening new ones unless the fit is extremely tight (near 0).
    if bin_residual < bin_capacity && fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64) * 0.5;
    }

    // 2. Harmonic Class Logic:
    // Identify "dead zones" where post_residual is small but unusable for common item sizes.
    // We penalize post_residuals that are in the range [1, 9] as they are likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Integration:
    // If next_item_size is large, we want to preserve bins with high post_residual.
    // If next_item_size is small, we can afford to pack into tighter residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item; penalize if it leaves a medium gap (10-30)
            // that is too small for the next item but too large to be considered "full".
            if post_residual > 10 && post_residual < 30 {
                score += 15.0;
            }
        } else {
            // This bin CAN fit the next item; reward this placement.
            score -= 10.0;
