    }

    // 4. Global State Awareness:
    // If mean_residual is high, we have many under-utilized bins. 
    // Discourage opening new bins (bin_residual == bin_capacity) if mean_residual is high.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Penalize opening a new bin if we have many fitting options already
        score += (fitting_bins_count as f64) * 5.0;
    }

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize packing density over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
