    // 2. Harmonic Class Logic: Prefer residuals that are multiples of common item sizes or bin fractions.
    // This helps align the bin to fit future items (e.g., 20, 25, 33, 50).
    let harmonic_alignment = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // 3. Lookahead Logic: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
