    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 4. Handle the "New Bin" candidate:
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual of open bins is already poor,
        // or if we have no fitting bins.
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Necessary evil
        }
    } else {
        // Penalize bins that are becoming too empty relative to the average
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }
    }

    // 5. Tie-breaker: prefer bins that are already "fuller" (lower post_residual)
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let capacity = bin_capacity as f64;

    // Best-Fit Decreasing logic: penalize large post_residuals (leaving too much space),
    // but normalize by capacity to handle the new-bin case (where post_residual = 100 - item_size).
    let mut score = post * post / capacity;

    // Penalty for creating a new bin: if this is a new bin (residual == capacity),
    // apply a penalty proportional to the stage of the stream.
    if bin_residual == bin_capacity {
        // As the stream progresses, we become more desperate to avoid new bins.
        // We add a significant baseline penalty that scales with open_bins_count.
        score += (capacity * 0.8) + (open_bins_count as f64 * 5.0) + (progress * 50.0);
    } else {
        // If we are placing in an existing bin, favor bins that bring the residual
        // closer to the global mean (balancing).
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;

        // Lookahead: if the next item is large, avoid bins that result in small, 
        // unusable residuals (the "fragmentation" trap).
        if next_item_size > 0 {
            if post < next_item_size as f64 && post > 0.0 {
                score += (next_item_size as f64 - post) * 1.5;
            }
        }

        // Criticality: if this is the only bin that can fit the item, 
        // aggressively prioritize it to avoid an unnecessary new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score. Lower is better.
    let mut score = post_residual as f64;

    // Penalty for leaving small "sliver" residuals that are difficult to fill (1-9)
    // Most items are >= 10, so a residual < 10 is effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic/Modulo bias: punish residuals that are "awkward" divisors of capacity
    // 100 / 3 = 33, 100 / 4 = 25, 100 / 5 = 20. 
    // If post_residual is near these, it's often a good fit for future items.
    let harmonic_penalty = match post_residual {
        20 | 25 | 33 | 50 => -20.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // If this is the only bin that can fit the item, we must take it unless 
    // it's a terrible fit (very large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New bin logic: only open a new bin if the current best existing bin 
    // is a very poor fit (e.g., leaving a large, unusable gap).
    if bin_residual == bin_capacity {
        // Only open new if we have many open bins already or if the average 
        // residual is high, suggesting we are wasting space.
        if open_bins_count > 5 && mean_residual > 20.0 {
            score += 10.0; 
        } else {
            score += 60.0; // Strong penalty for unnecessary new bins
        }
    }

    // Progression weight: as we approach the end of the stream, 
    // prioritize filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (1.0 - progress) * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
