    let mut score = post;

    // Penalty for creating a "fragmented" bin: if the post-residual is too small to fit 
    // common items (e.g., < 10) but not zero, it's wasted space.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Lookahead logic: if next_item_size is large and we currently have a bin that could 
    // potentially fit it, we penalize taking a bin that makes the current bin too small 
    // to accommodate that future item.
    if next_item_size > 0 {
