    }

    // Progression coupling: As the stream nears the end, prioritize filling existing bins 
    // (Best-Fit) over opening new ones. We increase the penalty for empty bins 
    // as progress increases.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
