        // Reward tighter fit for the next item
        score -= (post_residual - next_item_size) as f64 * 0.1;
    }

    // 3. Fragmentation penalty: If post_residual is small but > 0, it's often wasted space.
    // Penalize "slivers" (e.g., 1-9) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Mean residual balancing: Penalize bins that deviate significantly from the mean 
    // to keep the packing uniform across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // 5. New bin thresholding: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only choose a new bin if the current open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low
        if open_bins_count > 0 {
            score += 40.0;
        }
        // Increase penalty for new bins as we approach the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Last chance logic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining capacity. Lower is usually better (Best Fit).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that are hard to fill).
    // If post_residual is < 10, it's likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to avoid opening new ones.
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Global state pressure: If we have many open bins, penalize opening a new one 
    // (bin_residual == bin_capacity) unless the fit is perfect.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Fitting constraint: If this is the only bin that can fit the item, 
    // provide a slight incentive to take it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly 
    // from the current average residual to keep bin states uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_res.powf(1.5);

    // Penalty for leaving a bin with a "dead zone" (too small to fit typical items)
    // We define "dead" as < 10 (since minimum item size is effectively 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - post_res / 10.0);
    }

    // Lookahead logic: If the next item is large, penalize small residuals that prevent its placement
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.2;
