    // Stream progression adjustment:
    // Early in the stream, favor filling existing bins aggressively.
    // Late in the stream, be more conservative to avoid opening new bins.
    let density_factor = (open_bins_count as f64 * 100.0) / (step_index + 1) as f64;
    score += progress * density_factor * 5.0;

    // If this is a new bin (residual == capacity), penalize it based on how many
    // other bins could have accepted the item.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 25.0);
        // Reduce penalty if current bins are very full on average
        score -= (100.0 - mean_residual) * 0.5;
    }

    score
}

