    // We favor bins where the remaining space is small, but not so small it becomes "dead space".
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        // Reward bins that can perfectly accommodate the next item (zero delta).
        score -= (100.0 - fit_diff) * 2.0;
    }

    // 3. New Bin Penalty: Discourage opening a new bin unless the existing fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we are forced to open a new bin, we want to ensure it's not during the early stages
        // if we have plenty of open bins already.
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 5.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid leaving bins significantly emptier than the average.
    // If this bin's post_residual is much larger than the global mean, penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // 5. Scarcity Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive about fitting into existing space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
