        let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= utilization * 10.0;
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize 
    // filling current bins to minimize the total count regardless of fragmentation.
    if progress > 0.9 {
