    // We want to minimize post_residual (Best Fit).
    let mut score = post;

    // Penalty for creating "dead space": if the post_residual is too small to fit the next item,
    // but large enough to be wasted, we penalize it.
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            // Apply a non-linear penalty for fragmentation: (residual / next_item)^2
            // This discourages bins that become "useless" for the immediate future.
            score += (1.0 - (post / next_item_size as f64)).powi(2) * 50.0;
        }
    }

    // Dynamic pressure: As we near the end of the stream, we become more conservative
    // about opening new bins. We penalize the "New Bin" option (where bin_residual == bin_capacity)
    // more heavily as progress increases.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // We add a base cost of 25.0, then scale by progress to discourage new bins late in the game.
        score += 25.0 + (progress * 40.0);
    } else {
        // For existing bins, favor those that align the mean_residual with the current item,
        // reducing total entropy of bin states.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the only bin that can fit the item, we lower the score to prioritize
    // using it rather than opening a new bin (which would have a higher score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Interaction term: combine global state with local fit.
    // Penalize bins that are significantly emptier than the average.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    score
}

