        // Only open a new bin if we have many open bins already or if fitting_bins_count is low
        // This acts as a dampener to prevent excessive bin proliferation.
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Density Balancing: Prefer bins closer to the mean residual to keep distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 7. Progression scaling: Be more conservative as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
