    // Penalty for creating a new bin: scales with progress to favor consolidation early
    // and aggressive packing later.
    if is_new_bin {
        score += 25.0 + (progress * 45.0);
        // If we have many bins open, penalize opening a new one heavily
        score += (open_bins_count as f64).powf(1.2);
    } else {
        // Reward bins that bring the residual closer to the global mean (homogenization)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;

        // Lookahead: If next item fits in the current post_residual, prioritize this bin
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }

        // Penalty for leaving a 'dead' gap that is too small for any likely future item (10)
        if post_residual < 10 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Adjust for scarcity: if only one bin can fit the item, we are forced to use it.
    // If it's a poor fit, we might prefer a new bin if the score allows.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit policy)
    // Smallest post_residual is inherently good, but we penalize values that leave
    // "unusable" gaps (e.g., < 10, since min item size is likely 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that create "clean" residuals
    // (e.g., multiples of 25, 33, 50). These often leave space for standard item sizes.
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further refine: if we leave a perfect fit for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item,
    // we must take it unless the score is astronomically high.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. Global Density Control: If we are deep into the stream, bias towards
    // filling bins to capacity to reduce open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. New Bin Penalty: If bin_residual == bin_capacity, we are considering a new bin.
    // Penalize this heavily unless all other options are very poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

