    // it becomes a "sliver" that is hard to fill. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
    // reward this placement to maximize bin packing density (Best-Fit approach).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
