        let progress = step_index as f64 / total_items as f64;
        score += progress * 100.0;
    } else {
        // 4. If we are placing in an existing bin, favor keeping the mean_residual high 
        // to accommodate future large items, but prioritize tight fits.
        // If fitting_bins_count is 1, this is the only bin that can take the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Global density balancing: If the mean residual of current bins is very low, 
    // we are running out of space; prioritize placing in bins that maintain a higher residual.
    score += mean_residual * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
