    // Penalize opening new bins heavily early on, but allow it if it's the only option.
    // As progress approaches 1.0, favor tighter packing to finish the stream efficiently.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post * post;

    // Penalty for leaving small, unusable gaps (1-9 range)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - post);
    }

    // Interaction between next_item_size and post_residual
    // If we have a lookahead, favor bins that can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 + progress);
        } else {
            score += 15.0 * (1.0 - progress);
        }
    }

    // If this is the only bin that fits the current item, prioritize it to avoid 
    // fragmenting the bin count.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // If we are considering a new bin, apply a non-linear cost based on current efficiency
    if is_new_bin {
        // Base cost for opening a new bin, modulated by current mean residual
        // We want to avoid opening a new bin if the current mean residual is already high
        score = 500.0 + (mean_residual * 2.0) - (progress * 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
