        score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
    }

    // 3. Global State Awareness: If we have many open bins, penalize opening a new one 
    // or picking a bin that leaves us with high fragmentation.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress to avoid early fragmentation
        // but allows it if open_bins_count is low.
        score += 35.0 + (progress * 20.0);
        if open_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Encourage balanced filling of existing bins by comparing against the mean_residual
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 4. Critical Thresholding: If this is the only bin that fits the current item, 
    // we must prioritize it significantly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic Horizon: As we reach the end of the stream, prioritize tight packing 
    // to close out open bins.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
