    // Heuristic: Best-Fit Decreasing (BFD) logic enhanced with lookahead and bin utilization pressure.

    let mut score = post_residual as f64;

    // 1. Penalize creating very small, unusable gaps (1-9) which are often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the post_residual can perfectly or near-perfectly accommodate the next item,
    // prioritize this bin heavily (negative bias).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough space for the next item.
            score -= (20.0 * (next_item_size as f64 / (post_residual as f64 + 1.0)));
        }
    }

    // 3. Pressure Management: If this is the only bin that fits the current item, 
    // force its selection to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. Global Load Balancing: If we are early in the stream, favor filling existing bins 
    // to keep the bin count low. If late, prioritize tight packing to finish off bins.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    // 5. New Bin Penalty: Heavily penalize opening a new bin unless the current 
    // residuals are extremely poor (i.e., high mean_residual).
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.5);
    }

    // 6. Prefer bins that keep the overall mean residual low (packing density).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: Higher post_residual is usually bad (wasted space), 
    // but a very small post_residual (near 0) is excellent (Best Fit).

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small for common items).
    // If post_residual is between 1 and 9, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global state: If we are near the end of the stream, be more aggressive 
    // about filling existing bins to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Balance: Avoid opening a new bin if other bins are available.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // the current bin is a terrible fit for the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have other options.
            score += 55.0;
        }
    } else {
        // Reward bins that have residuals close to the mean_residual to keep 
        // usage uniform across bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. If fitting_bins_count is 1, this is the only bin that can take this item.
    // Strongly favor this bin to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bins heavily early on, but allow flexibility as the stream nears completion
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 - progress)).powf(1.5) + 25.0
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: Favor bins that leave the smallest residual
    // We add a non-linear penalty for larger residuals to encourage tight packing
    let fit_score = post.powf(1.8);

    // Lookahead logic: If the next item is large, avoid leaving a residual that cannot accommodate it
    // If post_residual is small but > 0, and the next item is large, this is a "dead space" trap.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        (next_item_size as f64 - post_residual as f64) * 2.5
    } else {
        0.0
    };

    // Encourage filling bins that are already "fragmented" (low mean_residual) to keep others empty
    // If open_bins_count is high, we want to consolidate into existing bins
    let consolidation_bonus = (open_bins_count as f64) * (mean_residual / bin_capacity as f64) * 5.0;

    // If this is the only bin that fits, prioritize it unless we are very early in the stream
    let exclusivity_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -20.0
    } else {
        0.0
    };

    fit_score + new_bin_penalty + lookahead_penalty - consolidation_bonus + exclusivity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit (Minimize post_residual)
    // The base score is already post_residual. We apply a non-linear penalty for large remaining gaps.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Penalize "Fragmented Space"
    // If a bin has space that cannot fit common item sizes (e.g., < 10), it is "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If next_item_size fits in the new post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Pressure Management: If fitting_bins_count is low, we are running out of options.
    // If this is the only bin that fits the current item, prioritize it to avoid new bin overhead.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. New Bin Thresholding (The "Empty Bin" Call)
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We penalize opening a new bin unless the current mean_residual is very high (meaning existing bins are already "bad").
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.5);
    }

    // 6. Global Progression: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

