    // but large enough to waste space (the "unusable gap" range 1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit/Tight-Fit Reward: Prefer bins that leave very little space.
    // If post_residual is 0, this is a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Lookahead Logic: If the next item can fit in the current post_residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 4. Global Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // as the stream progresses, unless necessary.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item,
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate negatively from the average
    // to keep bin utilization uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large remaining space (standard Best-Fit)
    // 2. Penalty for creating "Dead Space": If post_residual is small but > 0, it's often wasted.
    //    We heavily penalize residuals between 1 and 9 as they are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead integration: Try to match next_item_size to post_residual.
    //    If next_item_size fits in the post_residual, reward this bin highly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it fills the bin perfectly (Exact match)
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 4. Mean Residual constraint: Penalize bins that deviate significantly from the average
    //    open bin state to keep the packing density uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New Bin Management: 
    //    If this is a new bin (residual == capacity), penalize it relative to the scarcity of fitting bins.
    if bin_residual == bin_capacity {
        // If we have other bins that can fit the item, opening a new one is expensive.
        if fitting_bins_count > 0 {
            score += 65.0;
        } else {
            // Otherwise, we are forced to open a new bin.
            score -= 10.0;
        }
    }

    // 6. Progressive scaling: As we approach the end of the stream, prioritize closure.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
