pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit logic)
    // We penalize larger residuals quadratically to prefer tighter packs.
    let mut score = post.powi(2);

    // If this is a new bin (bin_residual == bin_capacity), apply a penalty
    // based on progress to discourage opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * (bin_capacity as f64).powi(2) * 0.5;
    }

    // Lookahead coupling: If the next item is large, penalize small post_residuals
    // that would "waste" the bin by being too small to accommodate the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            // This placement creates a "dead zone" for the next item.
            // Penalize proportional to the gap between post and next item.
            score += (next - post).powi(2) * 1.5;
        }
    }

    // Interaction with global state:
    // If we have many open bins, penalize new bins more aggressively.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 10.0;
    }

    // Fitting constraint: If this is the only bin that can fit the item,
    // lower the score to force usage and prevent premature new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

