    }

    // 3. Last Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Harmonic Alignment: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This helps keep bins "aligned" for future items.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 5. New Bin Discouragement: If the bin is new, apply a penalty that scales with progress.
    // As we reach the end of the stream, we become more desperate to avoid new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 + (progress * 20.0);
    }

    // 6. Mean Residual Balance: Avoid creating bins that are significantly 
    // more empty than the current average.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
