    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.5);
    }

    // Contextual pressure: if we have many open bins, prioritize closing them 
    // by picking bins that are near completion (low post_residual).
    // If fitting_bins_count is 1, this is the last chance for this item in an open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
