    // If the post_residual is smaller than the smallest likely item (approx 10),
    // it's often better to have a larger residual that can accommodate future items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // 4. Global state awareness: If we are near the end of the stream,
    // favor bins that are already partially filled to pack them to capacity.
