pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if necessary
    // Use a non-linear growth for the penalty to discourage premature fragmentation
    let new_bin_penalty = if is_new_bin {
        35.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Ideal fit is post_residual == 0 (perfect packing).
    // Penalize large post_residual (wasted space) quadratically.
    let fit_quality = (post_residual as f64).powf(1.5);

    // Lookahead logic: if we know the next item, penalize leaving a residual 
    // that is too small to accommodate the next item.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        // If the current placement makes the next item impossible in this bin, 
        // add a penalty proportional to the potential loss of packing efficiency.
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // Favor bins that are already "tight" if we are late in the stream
    let tightness_bonus = if !is_new_bin {
        (1.0 - (bin_residual as f64 / bin_capacity as f64)) * progress * 10.0
    } else {
        0.0
    };

    // Combine factors:
    // Lower score is better.
    fit_quality + new_bin_penalty + lookahead_penalty - tightness_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
