    }

    // Capacity Constraint: If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we should prioritize it unless the residual is extremely poor.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0; // Mild penalty for forcing a bad fit into the last available bin
    }

    // New Bin Logic: If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We penalize opening a new bin based on the current open bin density.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very tight.
        // If mean_residual is low, we are running out of space, so opening is justified.
        score += 30.0 - (mean_residual * 0.5) + (progress * 10.0);
    }

    // Harmonic Class Logic: Reward bins that align with modulo 25, 33, or 50 segments of capacity.
    // This helps group items of similar size classes together.
    let residual_class = post_residual % 25;
    if residual_class == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": gaps smaller than the smallest likely item (10)
    // or gaps that are too small to fit the next incoming item (lookahead).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Preference to open a new bin if nothing else fits
        }
    }

    // 3. Efficiency coupling: Favor bins that keep the post_residual close to the 
    // global mean residual to maintain uniform bin "tightness".
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Progress weighting: As the stream nears completion, prioritize closing 
    // existing bins (lower post_residual) over keeping many open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: We want the smallest post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We only open a new bin if the current fit is extremely poor or if we are forced to.
    if is_new_bin {
        // High cost to open a new bin, but scale it down as we near the end of the stream
        // to ensure we don't end up with many half-empty bins at the very end.
        score += 45.0 * (1.0 - progress);

        // If there are other bins that could fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // Reward placements that make the bin a perfect fit for the next item (Lookahead)
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= (100.0 - diff) * 0.15;

            // If the post_residual is exactly the next item size, it's a perfect match.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        }

        // Penalty for leaving "dead space" that is too small for any likely future item.
        // If post_residual is between 1 and 9, it is very likely to be unusable waste.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Deviation penalty: Try to keep bins packed similarly to the mean_residual.
        // This encourages uniform bin usage.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

