        if post_residual < 10 {
            score -= 15.0;
        }
        // If this bin is the only one that fits, reward keeping it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Dynamic thresholding based on mean_residual to avoid fragmented bins
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best-Fit approach)
    // We add a penalty for "Dead Space" (small residuals that are hard to fill)
    // A residual < 10 is often unusable for items >= 10.
    let dead_space_penalty = if post > 0.0 && post < 10.0 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Lookahead coupling: If the next item is large, avoid bins that leave little room
    // If next_item_size is 0, we are at the end, prioritize closing bins (lower residual)
    let lookahead_impact = if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Penalize bins that cannot fit the next item if we are forced to pick this bin
            15.0 * (1.0 - progress)
        } else {
            0.0
        }
    } else {
        // End of stream: aggressively minimize residual to finalize packing
        -post * 0.5
    };

    // Global state coupling: Encourage filling existing bins rather than opening new ones
    // as the stream progresses, penalize new bin creation (bin_residual == bin_capacity)
    let new_bin_penalty = if bin_residual == bin_capacity {
        (50.0 * (1.0 + progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Non-linear interaction: Normalize post_residual relative to the mean_residual
    // to keep the packing density high across all bins.
    let deviation_penalty = (post - mean_residual).powi(2) * 0.1;

    let score = post + dead_space_penalty + lookahead_impact + new_bin_penalty + deviation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
