        if (post_residual as f64) < mean_residual * 0.5 {
            score += 15.0;
        }
    }

    // 5. Harmonic Modulo Bias:
    // Favor residuals that align with common factors of bin_capacity (100).
    // Residuals like 25, 50, 20 are generally more flexible.
    if post_residual > 0 && (100 % post_residual == 0) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
