    // Favor bins that have fewer alternatives (fitting_bins_count).
    // If fitting_bins_count is 1, this is the last chance for this bin to be useful for this item.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New bin penalty: If this is a new bin (residual == capacity), add a significant penalty
    // to prevent opening new bins unless the fit in existing bins is objectively poor.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 15.0);
    }

