            // Reward bins that have just enough room for the next item.
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / 100.0);
        }
    }

    // 4. Global balance:
    // Avoid opening new bins if there are still fitting bins available.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin prematurely.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, normalize the cost of opening a new bin.
            score = 5.0; 
        }
    }

    // 5. Mean-residual alignment:
    // Avoid creating bins that are significantly emptier than the current average.
    if post_residual > (mean_residual as u32) && !is_new_bin {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead zones" (small residuals that are hard to fill).
    // Specifically, residuals between 1 and 9 are often unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization: If next item fits in the current post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Dynamic "New Bin" Penalty: 
    // If the bin is new (bin_residual == bin_capacity), penalize it based on 
    // how many existing bins could have fit the item.
    if bin_residual == bin_capacity {
        score += 25.0 + (fitting_bins_count as f64 * 15.0);

        // As the stream progresses, discourage opening new bins unless necessary.
        score += progress * 30.0;
    }

    // 4. Global state coupling: 
    // If our current bins are already very full (low mean_residual), 
    // prefer packing tightly to avoid fragmentation.
    if mean_residual < 20.0 {
        score += (20.0 - mean_residual) * 0.5;
    }

    // 5. Final tie-break: Prefer bins that result in smaller residuals 
    // (Best Fit logic) but modulated by the lookahead and state above.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize tightness (Best Fit)
    let mut score = post;

    // Penalty for creating 'dead space' (bins with very little capacity left)
    // We heavily penalize post_residual values in the range [1, 9] to avoid fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If a future item is large, favor keeping space open.
    // If next_item_size is large (> 60), we penalize small residuals in current bins.
    if next_item_size > 60 && post_residual < next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins to reduce the total number of open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // High priority to finish off a bin that is the only one fitting the item
        score -= 20.0 * progress;
    }

    // New bin penalty: Only open a new bin if the existing fits are truly poor.
    if bin_residual == bin_capacity {
        // Scaling the cost of opening a new bin by the current mean_residual.
        // If mean_residual is low, we are already efficient, so make opening new bins expensive.
        score += 40.0 + (mean_residual * 0.5) + (20.0 * progress);
    }

    // Non-linear coupling: penalize bins that deviate significantly from the mean_residual
    // to promote uniform packing density across the bin set.
    let dev = (post - mean_residual).abs();
    score += 0.2 * dev.powi(2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Harmonic/Modulo logic: Penalize residuals that cannot easily fit common item sizes (10, 20, 25, 33, 50).
    // Small residuals (below 10) are extremely valuable if they are 0, otherwise they are "dead" space.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 20.0; 
    }

    // Lookahead logic: If the next item can fit perfectly in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let remainder = post_residual - next_item_size;
        if remainder == 0 {
            score -= 40.0;
        } else if remainder < 10 {
            score -= 15.0;
        }
    }

    // Fitting threshold: If this is the only bin that fits the current item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New Bin Penalty: If bin_residual == bin_capacity, we are considering a new bin.
    // Scale the penalty for opening a new bin based on progress and current fragmentation.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5) + (progress * 10.0);
    }

    // Harmonic pressure: Penalize bins that deviate significantly from the mean occupancy.
    let occupancy = (bin_capacity - bin_residual) as f64;
    score += (occupancy - (bin_capacity as f64 - mean_residual)).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
