            score -= 20.0;
        }
    }

    // 4. Global Density Awareness: If the mean residual is high, we are 
    // being too inefficient; penalize bins that increase that mean.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize 
    // packing density over future flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing (BFD) logic with lookahead pressure.
    // We aim to minimize post_residual (Best Fit) but penalize fragmentation
    // based on whether the next item could have fit better elsewhere.

    let mut score = post_residual as f64;

    // 1. Fragmentation Penalty: Penalize leaving small gaps that are hard to fill.
    // If post_residual is small (e.g., < 10), it is "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor bins that can still accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item.
            score -= 15.0;
        } else {
            // Penalize bins that block the next item if other bins are available.
            score += 10.0;
        }
    }

    // 3. Global Efficiency: Balance against mean_residual to prevent premature bin opening.
    // If our current bin is already much emptier than the average, we are wasting space.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 5.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or the state is congested.
        // Penalty for opening a new bin is dynamic based on progress.
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 + (10.0 * progress);

        // If we have many fitting bins, opening a new one is almost always bad.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 15.0;
        }
    }

    // 5. Final adjustment: Prefer bins that are nearly full (Best Fit)
    // but normalize by the number of open bins to encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalty for creating small, unusable gaps (the "fragmentation" trap).
    // Quadratic penalty on post_residual to favor tight fits, but modulated by progress.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 15.0 {
        (15.0 - post_res).powi(2) * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that can accommodate the next item (lookahead).
    let lookahead_reward = if next_item_size > 0 && post_res >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Strategic bias: As the stream nears the end, prioritize filling bins to capacity
    // to avoid leaving trailing empty space.
    let closure_incentive = if progress > 0.85 {
        post_res * 2.0
    } else {
        post_res * 0.5
    };

    // Bias against opening new bins unless necessary.
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one is available.
            40.0 + (open_bins_count as f64 * 5.0)
        } else {
            // Necessary new bin, minimize its residual footprint.
            0.0
        }
    } else {
        0.0
    };

    // Combine factors:
    // Lower score is better.
    post_res + fragmentation_penalty + lookahead_reward + closure_incentive + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
