    // for future items. We reward post_residuals that are multiples of common item sizes.
    let harmonic_penalty = (post_residual % 10) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead integration:
    // If next_item_size fits in the current post_residual, drastically reduce the score (reward).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Fitting constraints:
    // If fitting_bins_count is low, we are constrained. If this is the only bin that fits,
    // we should prioritize it unless it creates a very poor residual.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0; // Discourage using the last available bin if it wastes too much space
    }

    // 5. Empty Bin Threshold (The "New Bin" gate):
    // If this is an empty bin (bin_residual == bin_capacity), set a threshold cost
    // to discourage opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is influenced by the current mean_residual.
        // If the current bins are already very full, opening a new one is more acceptable.
        score = 45.0 + (mean_residual * 0.2);
    }

    // 6. Progress weight: As we near the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
