        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Global state coupling: Encourage keeping residuals near the mean to maintain balance.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Last chance bonus: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large empty spaces (waste) heavily, but modulate by stream progress.
    // Near the end of the stream, we want to be more aggressive in filling bins (lower tolerance for waste).
    let waste_penalty = post.powf(1.5) * (1.0 + progress);

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we create a "dead" bin for the next step.
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            lookahead_penalty = (next_item_size as f64 - post_residual as f64) * 2.5;
        }
    }

    // Favor bins that align with the current mean residual to keep bin states uniform.
    let dispersion_penalty = (post - mean_residual).abs() * 0.5;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy opening cost.
    // The cost decreases slightly as the stream progresses to allow for better packing at the end.
    let opening_cost = if bin_residual == bin_capacity {
        (50.0 - (progress * 20.0))
    } else {
        0.0
    };

    // If this is the only bin that fits the current item, lower its score to prevent unnecessary new bins.
    let urgency_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -40.0
    } else {
        0.0
    };

    waste_penalty + lookahead_penalty + dispersion_penalty + opening_cost + urgency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // We favor bins that result in small residuals.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin unless existing bins are very tight.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Harmonic Fragmentation Control:
    // If we are forced to leave a small gap that is unlikely to be filled by the remaining stream,
