pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize fragmentation: bins that are nearly empty but not completely empty are often worst.
    // We use a quadratic penalty on the post_residual to favor Best-Fit behavior.
    let base_score = post_res * post_res / 100.0;

    // Lookahead logic: if the next item is large, favor keeping larger residuals (higher post_res).
    // If next_item_size is 0 (end of stream), we aggressively minimize post_residual.
    let lookahead_factor = if next_item_size > 0 {
        (next_item_size as f64 - post_res).max(0.0) * 0.5
    } else {
        0.0
    };

    // Smooth transition: As we approach the end of the stream (progress -> 1.0), 
    // we become more aggressive about filling bins (penalizing larger post_residuals more).
    let progress_penalty = post_res * progress * 0.5;

    // Penalty for opening a new bin: if bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize this unless the current open bins are too full to accommodate future items.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 { 0.0 } else { 50.0 + (open_bins_count as f64 * 2.0) }
    } else {
        0.0
    };

    // Coupling: If the mean residual of current bins is high, we are being too loose; 
    // force tighter packing by increasing the score of non-optimal fits.
    let density_adjustment = (mean_residual - post_res) * (1.0 - progress);

    base_score + lookahead_factor + progress_penalty + new_bin_penalty + density_adjustment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
