    // fitting options are extremely poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the average residual is already quite low,
        // suggesting we are wasting space in existing bins, or if we have few open bins.
        score += 200.0 + (open_bins_count as f64 * 10.0);
    } else {
        // If this is the last chance for the current item, reward it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // 4. Global Efficiency: If the current bin is significantly worse than the 
    // global mean, penalize it to force consolidation.
    if (post_residual as f64) > mean_residual {
