    // We add a penalty for empty bins to discourage opening them unless necessary.
    let mut score = post * post;

    // Penalty for creating 'dead space' that is too small to fit common small items (e.g., < 15).
    // This is non-linear to aggressively avoid 'sliver' residuals.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powi(3);
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough room.
    // If next_item_size is large (e.g., > 60), we penalize small residuals.
    if next_item_size > 60 {
        if post < 60.0 {
            score += (60.0 - post).powi(2);
        }
    }

    // Dynamic threshold: As the stream progresses, become more conservative about opening new bins.
    // We penalize the 'new bin' option (bin_residual == bin_capacity) using progress.
    if bin_residual == bin_capacity {
        // The base cost of opening a new bin increases as we approach the end of the stream.
        score += 500.0 * (1.0 + progress);

        // If there are many open bins, penalize opening a new one heavily.
        score += open_bins_count as f64 * 50.0;
    } else {
        // If we are in a bin that is already open, favor bins that align with the mean_residual
        // to keep usage density uniform across active bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 2.0;
    }

    // If this is the last available bin that can fit the item, give it a significant boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

