    }

    // 5. Global state management: Prevent excessive bin opening
    // If we have many open bins, prioritize filling them (lower score)
    // If we have very few bins, be more selective (higher score)
    score += (open_bins_count as f64 * 2.0);

    // 6. Last chance logic: If this is the only bin that fits, force it to be the best choice
    if fitting_bins_count == 1 && bin_residual >= item_size {
