    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the number of currently open bins.
    score += (post_residual as f64).powf(1.2) * (1.0 + (open_bins_count as f64 * 0.05));

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin heavily to keep the bin tight.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive 
    // about filling bins (Best-Fit) to avoid leaving too many bins open.
    if fitting_bins_count > 0 {
        // If we are late in the stream, prioritize fitting into existing bins 
        // to prevent opening a new one.
        score -= (progress * 50.0);
    }

    // 4. New Bin Logic: If this is an empty bin, calculate a penalty based 
    // on current fragmentation. Opening a new bin should be a last resort.
    if bin_residual == bin_capacity {
        // New bin penalty: Higher if we have open bins that could fit the item.
        // We only open a new bin if the average residual of open bins is already very small.
        let penalty = 150.0 + (open_bins_count as f64 * 10.0) - (mean_residual * 0.5);
        score += penalty;
    } else {
        // 5. Fragmentation Avoidance: If the post_residual is small (e.g., < 10),
        // it creates 'dead' space. Penalize this unless it's a perfect fit (0).
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it is often harder to fill later. We penalize values in the [1, 15] range.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res) * 2.5;
    }

    // Lookahead logic: if next_item_size is known, favor bins that accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item perfectly
            score -= (1.0 - (post_res - next_item_size as f64).abs() / 100.0) * 10.0;
        } else {
            // Penalize bins that will force a new bin for the next item
            score += 5.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower mean_residual)
    // to prevent fragmentation towards the end of the stream.
    if open_bins_count > 0 {
        let deviation = (post_res - mean_residual).abs();
        score += deviation * progress;
    }

    // New Bin Logic: Only open a new bin if the best existing fit is extremely poor
    // or if fitting_bins_count is low and we have significant capacity remaining.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open
        } else {
            // Make opening a new bin expensive unless the current fitting bins are terrible
            score = 50.0 + (progress * 30.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
