        // If fitting_bins_count is high, opening a new bin is a bad idea.
        score += (fitting_bins_count as f64) * 30.0;

        // Also penalize opening new bins if we are near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // Reward using existing bins based on how well they align with the global mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // 5. Fitting constraint: Strongly discourage leaving only one bin that can fit the item
    // if that bin is currently very full.
    if fitting_bins_count == 1 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
