pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" option heavily as the stream progresses to favor consolidation
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Calculate "tightness" penalty: 
    // Small residuals (below 10) are extremely valuable (Best Fit).
    // Medium residuals (10-30) are "dead zones" that make future packing hard.
    let tightness_penalty = if post < 10.0 {
        -20.0 + post // Reward very tight fits
    } else if post < 30.0 {
        (post - 10.0) * 1.5 // Penalize creating mid-sized gaps
    } else {
        (post - 30.0) * 0.5 // Linear cost for large gaps
    };

    // Lookahead influence: If the next item is large, prioritize keeping space open.
    // If next_item_size > post_residual, this bin will be "useless" for the next step.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        15.0 * (1.0 - progress)
    } else {
