    };

    // Global state awareness: If we have many open bins, penalize opening new ones 
    // or picking bins that increase the mean_residual significantly.
    let efficiency_pressure = (open_bins_count as f64 * 0.5) + (mean_residual * 0.1);

    score = post + new_bin_penalty + tightness_penalty + lookahead_penalty + efficiency_pressure;

    score
}

