pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize post_residual values that are likely to be wasted.
    // Gaps between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open bins pressure: If many bins are already open, penalize opening a new one.
    // The new bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Tight fit reward: Prefer bins that are nearing capacity to reduce the number of active bins.
    // We reward small post_residuals only if they are not in the "dead zone".
    if post_residual >= 10 && post_residual <= 20 {
        score -= 10.0;
    }

    // 5. Fitting bin scarcity: If this is the only bin that can fit the item, prioritize it 
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Global efficiency: Favor bins closer to the current mean residual to keep bin states uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best-Fit behavior by penalizing large post_residuals
    // but subtract a large value if it results in a perfect fit (zero residual).
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Lookahead logic: If post_residual is nearly perfect for the next item, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 2.5;
        } else {
            // Penalize if this bin will definitely NOT fit the next item 
            // when it could have if we chose a different bin.
            score += 50.0;
        }
    }

    // 3. Prevent excessive bin opening: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the item fits nowhere else or fitting_bins_count is very low.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 100.0; // Necessary evil
        }
    }

    // 4. Global balance: If the post_residual is significantly lower than the 
    // current mean_residual, it is a "tight" fit, which is generally good.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // be more aggressive about filling existing space.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: reward smaller post_residuals (tight packing)
    // 2. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // If post_residual is < 10, it's likely wasted space unless next_item is very small.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 3. Lookahead integration: If next item fits in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Global state: If we are running out of items, be more aggressive with packing (lower score).
    // If we are early in the stream, avoid creating too many open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // Encourage finishing off bins that are the only option
    }

    // 5. Penalize opening a new bin (bin_residual == bin_capacity) unless necessary.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the mean residual of existing bins is already tight (bad for new items)
            // or if the current item is very large.
            let threshold = 20.0 + (progress * 30.0);
            if mean_residual < 20.0 || item_size > 70 {
                score += threshold;
            } else {
                score += 100.0; // Strongly discourage opening new bins early
            }
        }
    }

    // 6. Dynamic balance: favor bins whose residual is close to the mean to keep bin states uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post_res;

    // Penalty for creating a bin that is too small for the next item (Dead Space avoidance)
    // If next_item_size is large, we want to prioritize bins that can fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Dynamic thresholding: discourage opening new bins as the stream nears completion
    // unless the fit is perfect (post_residual == 0).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress).powf(0.5);
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Coupling: penalize bins that deviate significantly from the mean residual of open bins.
    // This promotes "bin leveling" (keeping residual space uniform).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    // Favor bins that are "last chance" for the current item to reduce bin count.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Non-linear penalty for fragmentation: if the residual space is small but unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit strategy)
    // The base score is already post_residual, which inherently favors tight fits.

    // 2. Harmonic Class Logic: Penalize creating "dead zones" that cannot fit common item sizes.
    // We heavily penalize residuals that are small but unusable (1..9), 
    // as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // we reward this placement to keep bins consolidated.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity/Efficiency: If this is the only bin that fits the item (fitting_bins_count == 1),
    // prioritize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // 5. New Bin Threshold: If we are evaluating a brand-new empty bin (bin_residual == bin_capacity),
    // we apply a steep penalty to prevent opening new bins unless the existing ones are truly poor matches.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already quite low,
        // suggesting that existing bins are too full to accommodate future variance.
        score += 35.0 + (mean_residual * 0.5);
    }

    // 6. Progression Weighting: As the stream nears completion, become more aggressive 
    // about filling remaining space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
