pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing (BFD) logic: prioritize smaller post_residual
    // 2. Penalty for creating "fragmented" space (1-9) that is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 3. Lookahead synergy: If post_residual is nearly perfect for the next item, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = post_residual - next_item_size;
            // Reward placement that makes the next item fit perfectly or with minimal waste
            score -= (100.0 - waste as f64) * 0.5;
        } else {
            // Penalty if this placement prevents the next item from fitting in this bin
            score += 20.0;
        }
    }

    // 4. Global balance: If we have too many open bins, penalize opening new ones (bin_residual == capacity)
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.0) + (100.0 - mean_residual);
    }

    // 5. Criticality: If this is the only bin that fits the current item, prioritize it to avoid new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress adjustment: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too fragmented to fit future items.
    // If post_residual is small but > 0, it is often a "dead zone".
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin heavily to create a "combo".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // If this is a new bin, penalize it based on how many bins are already open 
    // and how much room is left in existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to or if existing bins are very full.
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Prefer opening a new bin if nothing else fits.
        }
    } else {
        // Reward bins that have residuals closer to the mean to keep bins balanced.
        let diff_from_mean = (bin_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;
    }

    // Dynamic horizon: as we near the end of the stream, prioritize aggressive packing.
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    let mut score = post;

    // Penalty for leaving a "sliver": space too small for almost any item (1-9)
    // We penalize very small residuals heavily to avoid fragmentation.
    if post > 0.0 && post < 10.0 {
        score += 50.0 / (post + 1.0);
    }

    // Lookahead logic: If a future item exists, prioritize bins that keep 
    // enough space to fit it, weighted by progress in the stream.
    if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post < needed {
            // Penalize bins that would make it impossible to fit the next item
            score += 20.0 * (1.0 + progress);
        } else {
            // Reward bins that maintain enough room for the lookahead item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Adaptivity: If we are near the end of the stream, prioritize aggressive packing
    // (low post_residual) over keeping bins open.
    if progress > 0.8 {
        score += post * 2.0;
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open if the existing bins are poorly suited (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins prematurely.
        // We reduce this penalty if we have very few fitting bins, 
        // suggesting current bins are already too full.
        let scarcity_factor = if fitting_bins_count < 2 { 15.0 } else { 45.0 };
        score += scarcity_factor + (mean_residual * 0.5);
    }

    // Interaction term: penalize bins that deviate significantly from the mean_residual
    // to encourage uniform fill levels across the set of open bins.
    let dev = (post - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large empty spaces (Best-Fit principle)
    // We add a non-linear weight to the residual to prioritize tight fits.
    score += (post_residual as f64).powf(1.5);

    // Harmonic class logic: prioritize values that leave "clean" remainders (multiples of 5 or 10)
    // which are more likely to accommodate future items in a constrained range.
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead logic: if next_item_size is known, penalize bin configurations that 
    // leave insufficient space for the next item, unless it's the last item.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0;
    }

    // Penalize opening a new bin if other bins can fit the item.
    // We use fitting_bins_count to identify the 'new bin' case (where fitting_bins_count == 0 for the new bin).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that have small residuals compared to the mean (Best Fit refinement)
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Dynamic scaling based on stream progression
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it's too small to fit any likely future item.
    // Assuming a distribution where items are often >= 10, a residual < 10 is "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Bin Pressure: If this is the only bin that can fit the item, favor it heavily to prevent new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. Open Bin Constraint: Penalize opening a new bin proportionally to the current count.
    // This forces the algorithm to consolidate items into existing bins as the stream progresses.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Mean Residual Alignment: Penalize bins that deviate too far from the average state,
    // encouraging a uniform distribution of fill levels across all active bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor bins where post_residual is as small as possible.
    score += post_residual as f64 * 1.2;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // reward this bin heavily to create a perfect pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further refine: favor tightest fitting for the pair
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Thresholding: Prevent premature opening of new bins.
    // If this is a new bin, penalize it unless no other bin is a good fit.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we are at the end of the stream, be more conservative with new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 4. Mean Residual Balancing: Avoid leaving bins significantly emptier than the average.
    // If this bin's post_residual is much lower than the mean, it's a good candidate.
    if post_residual < mean_residual as u32 {
        score -= (mean_residual - post_residual as f64) * 0.8;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy:
    // 1. Best-Fit approach: Minimize post_residual (the waste).
    // 2. Lookahead: Penalize placements that make the next item harder to fit.
    // 3. Efficiency: Penalize opening new bins unless the current bins are very full.

    let mut score = post_residual as f64;

    // Penalty for creating a bin that is "too empty" (under 20 remaining space)
