    }

    // Lookahead: If next_item_size exists, penalize bins that leave just enough space
    // to be "useless" (e.g., 1-9 space) for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 30.0;
    }

    // Encourage filling bins that are already "near full" to reduce open_bins_count.
    // If post_residual is small, we reward it more aggressively as the stream progresses.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // If this is a new bin (bin_residual == bin_capacity), force a high cost unless
    // it's the only option or the current bins are too fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have fitting options.
            score += 60.0 + (open_bins_count as f64 * 5.0);
        } else {
            // Base cost for new bin.
            score += 10.0;
        }
    }

    // Dynamic adjustment based on mean_residual: 
    // If mean_residual is high, we are wasteful, so be more selective.
    score += mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
