    // If this is the last chance for the current bin (fitting_bins_count == 1), 
    // lower the score to encourage filling existing bins before opening new ones.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New bin dynamic threshold: Only open a new bin if the current mean_residual is already 
    // quite tight, or if we are early in the process and need to avoid fragmentation.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only consider a new bin if the average residual of existing bins is already 
            // smaller than the item size (forcing a new bin eventually anyway).
            let threshold = if mean_residual < item_size as f64 { 10.0 } else { 85.0 };
            score = threshold + (progress * 10.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // Penalize large post_residual (wasted space)
    let mut score = post * 1.5;

    // Non-linear coupling: Exponentially penalize small post_residuals 
    // that are too small to fit the next item, specifically as the stream progresses.
    if next_item_size > 0 && (post_residual < next_item_size) {
        score += (next_item_size as f64 - post) * (1.0 + progress * 2.0);
    }

    // Dynamic penalty for opening new bins:
    // If the bin is new (residual == capacity), add a penalty that scales 
    // with the current average density (mean_residual). 
    // We want to avoid opening new bins unless the current bins are very full.
    if bin_residual == bin_capacity {
        let density_factor = (capacity - mean_residual) / capacity;
        score += 25.0 + (density_factor * 50.0 * (1.0 - progress));
    }

    // Multi-bin pressure: If only one bin can fit the item, 
    // reduce the penalty for a poor fit to ensure we don't overflow the bin capacity
    // or force an unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Interaction term: Penalize bins that create "dead zones" (residuals < 10)
    // that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize tiny residuals that are unlikely to accommodate future items.
    // Specifically, if post_residual is in (0, 10), it's a "dead zone" hazard.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Logic: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Harmonic Class Bias: Prefer bin fillings that leave multiples of common sizes (e.g., 20, 25, 33).
    // This helps pack future items of similar classes.
    let remainder_mod = post_residual % 25;
    score += remainder_mod as f64 * 0.5;

    // 4. New Bin Thresholding: Adjust the cost of opening a new bin.
    // If we are late in the stream, we are more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high.
        score = 65.0 + (progress * 20.0);

        // If there are many bins open, penalize opening another one even more.
        score += open_bins_count as f64 * 2.0;
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, 
    // it is highly prioritized (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean occupancy.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit typical future items
    // (We treat 1..9 as 'unusable' dead space for the 10..80 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on current open bin count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: If the current bin is emptier than the mean, prefer filling it to keep
    // the mean_residual tighter (Best-Fit principle).
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // 6. Progressive Tightening: As we approach the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Lower post_residual is generally better.
    // However, we penalize very tight fits (e.g., < 5) if they create "orphan" space.
    if post_residual < 5 && post_residual > 0 {
        score += 15.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space,
    // prioritize this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = post_residual - next_item_size;
            // Reward bins that leave exactly enough room for the next item.
            score -= (50.0 - waste as f64) * 0.8;
        } else {
            // If next item does not fit, penalize based on how close we are to 
            // filling the bin, avoiding fragmentation.
            score += 5.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless existing 
    // options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but scales with how poorly
        // the current items fit into existing bins (mean_residual).
        score = 60.0 + (mean_residual * 0.5);
    } else {
        // 4. Fitting Pressure: If this is the last bin that can fit the item,
        // reduce the score to force the placement.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // 5. Global density balancing: Favor keeping residuals closer to the mean
        // to prevent extreme outliers.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to prioritize tight packing.
    // However, if the post_residual is small (e.g., < 5), it creates "fragmentation" 
    // which is often worse than a slightly larger residual.
    if post_residual < 5 && post_residual > 0 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we should prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State Balancing: Use mean_residual to avoid creating bins that are 
    // significantly worse than the average state of the system.
    if (post_residual as f64) > mean_residual {
        score += 10.0 * (1.0 - progress);
    }

    // 4. Threshold Logic: If this is the only bin that fits, we are forced to take it,
    // but if it's a "new bin" (bin_residual == bin_capacity), we penalize it 
    // increasingly as the stream progresses to force consolidation.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (progress * 30.0);
        }
    } else {
        // If it's an existing bin, reward it if it's the last chance (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Dynamic Horizon: As we reach the end of the stream, prioritize closing bins
    // by being more aggressive on existing capacity.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps that are too small for common items (10-30 range)
    // but favor tight fits that leave almost no room.
    let gap_penalty = if post < 10.0 {
        post * 0.5
    } else {
        post * 1.5 + (post * post / 20.0)
    };

    // Lookahead logic: if next item is large, favor larger residuals now to accommodate it.
    // Use non-linear coupling with progress to shift from Best-Fit to First-Fit as stream ends.
    let lookahead_mod = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        (diff * (1.0 - progress)) * 0.8
    } else {
        0.0
    };

    // Penalize opening new bins heavily early on, but allow more flexibility as we near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * (1.0 - progress)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Encourage filling bins that are already closer to the mean residual to keep bin states uniform
    let uniformity_bonus = (post - mean_residual).abs() * 0.2;

    // Combine: lower is better.
    // New bins start with high penalties that decay as the stream progresses.
    // Tight fits are rewarded.
    gap_penalty + lookahead_mod + new_bin_penalty + uniformity_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing
    // We scale by a factor to ensure post_residual is the primary driver.
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // This creates "shelves" for future items. If post_residual is near 0 or 25, 33, 50, 
    // it increases the probability of fitting future large items.
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 0.2;

    // 3. Lookahead Integration: If the next item fits into the current post_residual, 
    // reward this bin heavily to create a "double-pack" effect.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity/Efficiency weighting: If fitting_bins_count is low, 
    // we are approaching the limit of current capacity; prioritize closing this bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // add a high constant penalty to discourage opening new bins unless 
    // all other options are extremely inefficient (high post_residual).
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average residual,
    // which helps maintain uniform bin fill levels.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are rarely useful given item range 10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins if there are still fitting options
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0 + (open_bins_count as f64 * 5.0);
    }

    // 3. Lookahead: If the next item could fit in the current post_residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
