    // If the post_residual is close to the mean, we preserve the distribution
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Pressure: As the stream progresses, discourage keeping too many open bins
    let progress = step_index as f64 / total_items as f64;
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // 6. Prefer tighter fits (Best Fit heuristic base)
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual (Best Fit), but penalize placements that leave
    // a "dead zone" (remaining space too small for any likely future item).
