    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Mean residual balancing: If current bin residual is significantly higher than
    // the mean of other bins, we want to fill it to normalize the bin states.
    if (bin_residual as f64) > mean_residual {
