    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too empty early in the stream.
    // If post_residual is large and we are early, we penalize it to force tighter packing.
    score += (post * post / bin_capacity as f64) * (1.0 - progress);

    // Lookahead logic: if the next item is large, we want to reserve space for it.
    // If the current post_residual is smaller than the next_item_size, we penalize 
    // the bin because it effectively "wastes" the ability to hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Heuristic for opening a new bin:
    // If bin_residual == bin_capacity, this is a new bin candidate.
    // We only want to open a new bin if the current mean_residual is very low (bins are full),
    // or if we are forced to (fitting_bins_count is low).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very tight.
        score += 25.0 * (1.0 - (mean_residual / bin_capacity as f64));

        // If we have very few fitting bins, opening a new bin becomes relatively more attractive.
        if fitting_bins_count < 2 {
            score -= 10.0;
        }
    }

    // Penalty for fragmentation: penalize bins that deviate significantly from the mean_residual.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
