    // If this is a new bin (bin_residual == bin_capacity), penalize based on current open count.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Balancing: Prefer bins that are already closer to the mean residual to keep packing uniform.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Criticality: If this is the only bin that fits the current item, 
    // significantly lower its score to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Progressive constraint: As we approach the end of the stream, 
    // prioritize tighter packing (lower residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
