pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize post_residual, but we penalize bins that leave 
    // "unusable" space (e.g., space < 10) unless the item is the last one.
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" of space that is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // Heuristic: If we are late in the stream, be more aggressive with packing (Best Fit)
    // If we are early, be more lenient to keep bins open for potential future fits
    if !is_new_bin {
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 5.0 * progress;
    }

    // Lookahead logic: if next_item fits in the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Penalty for opening a new bin:
    // Only open a new bin if we are forced to (fitting_bins_count == 0)
    // or if the current open bins are all very poorly suited (high mean_residual)
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can fit the item
            score += 80.0 + (mean_residual * 2.0);
        } else {
            // If no bins fit, new bin is the only option
            score = 0.0;
        }
    }

    // Global pressure: as total items approach, prioritize closing existing bins (minimize open_bins_count)
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
