        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 5.0;
    }

    // 3. Lookahead Synergy: If a next item exists, reward bins that leave enough space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Fragmentation penalty: we left space but can't fit the next item
            score += 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Density: Toward the end of the stream, prioritize tight packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
