    // to force consolidation towards the end.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + 50.0 * progress);

    // Minimize post_residual, but penalize "fragmentation" (small remaining space that is hard to fill).
    // Specifically, if post_residual < 10, it's likely dead space.
    let fragmentation_penalty = if post_res < 10.0 && post_res > 0.0 {
        15.0 * (1.0 - post_res / 10.0)
    } else {
