    }

    // 4. Global Density Calibration: As the stream progresses, prioritize closing bins
    // by penalizing empty space more aggressively when many bins are already open.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    // 5. Mean Residual Balancing: If this bin's residual is significantly lower than the 
    // global mean, it is a "tight" bin. Reward filling it further to consolidate space.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
