    // Tighten fit requirements as we progress through the stream.
    if !is_new_bin {
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 10.0 * (1.0 + progress);
    }

    // 4. Critical thresholding: If this is the last chance to fit an item,
    // reduce the penalty for a poor fit to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
