    // 1. Best-Fit Penalty: Penalize leaving small, unusable gaps.
    // If post_residual is small but not zero, it's often a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If the next item fits into the current post_residual,
    // prioritize this bin to preserve future capacity in other bins.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. New Bin Management: Discourage opening a new bin unless the remaining
    // capacity in existing bins is heavily fragmented.
    if bin_residual == bin_capacity {
        // High penalty to open new bin if existing ones have good capacity.
        if mean_residual > 20.0 {
            score += 30.0;
        } else {
            score += 70.0;
        }
    }

    // 4. Fitting Density: If this is the last chance for the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Harmonic Class Coupling: Favor bins that leave a residual which is a 
    // multiple of common item sizes (20, 25, 33), as they are more "flexible".
    let mod_val = post_residual % 25;
    if mod_val == 0 {
        score -= 10.0;
    }

    // 6. Progression Weighting: As the stream nears the end, be more aggressive 
    // about filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
