    // If post_residual is in the "danger zone" (1..10), it is highly likely to become permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Integration: If next item is large, prioritize bins that leave enough room.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0; // Penalty for stranding a large item
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless it is the only option (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        } else {
            // New bin is necessary, normalize score to be competitive
            score = 15.0; 
        }
    }

    // 4. Fitting Density: Favor bins that are already "tight" to keep open_bins_count low.
    // We prefer bins that bring the mean_residual down.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive
    // about closing bins (higher penalty for new bins).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
