pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize "Best Fit" (smallest post_residual) while penalizing the creation of "dead space"
    // that cannot accommodate the next known item (lookahead) or the general average item size.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize new bins heavily, but decrease penalty as we approach the end of the stream
    // to allow for finishing off bins without forcing sub-optimal placements.
    if is_new_bin {
        score += 45.0 * (1.0 - progress);
        // If other bins can fit the item, opening a new one is usually bad
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Lookahead logic: if we know the next item, penalize leaving a residual that 
    // is too small for it, but too large to be considered "full".
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 5 {
            // This is a "bad" gap: too small for next item, but wasteful
            score += 25.0;
        } else if post_residual >= next_item_size {
            // This is a "good" gap: can accommodate next item
            score -= 10.0;
        }
    }

    // Global state awareness: if our average residual is high, we are being too loose.
    // Tighten up by penalizing bins that leave more than the current mean.
    if post_residual as f64 > mean_residual {
        score += 5.0 * (post_residual as f64 / (mean_residual + 1.0));
    }

    // Final check: if this is the only bin that can fit the item, 
    // heavily incentivize choosing it over opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement.
    // Minimizing post_residual is the Best-Fit principle.
    let mut score = post;

    // Penalty for leaving a very small, unusable gap (fragmentation).
    // If post_residual is in (0, 10), it is highly likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large and won't fit in the remaining space,
    // we penalize this placement to keep the bin open for the next item.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, we become more conservative 
    // about opening new bins. If fitting_bins_count is 1, we are at a decision point.
    // We penalize the "New Bin" option (bin_residual == bin_capacity) 
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + (30.0 * progress);

        // If we have many open bins, opening another is costly.
        score += (open_bins_count as f64) * 2.0;
    }

    // Coupling: If the post_residual is close to the mean_residual of other bins,
    // we favor it to keep bin states uniform, which helps future packing.
    let residual_diff = (post - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
