        score += 50.0 + (open_bins_count as f64 * 2.0 * (1.0 - progress));
    } else {
        // Reward bins that bring the residual close to the mean, promoting balanced fill levels
        let residual_variance = (post_residual as f64 - mean_residual).abs();
