    // 5. New Bin Penalty: If the bin is empty (bin_residual == bin_capacity), 
    // apply a significant penalty to force the algorithm to prefer existing bins.
    if bin_residual == bin_capacity {
        // The penalty scales with how many open bins are available to discourage 
        // opening new bins when capacity is already spread out.
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Balance the mean residual: If this bin is significantly emptier than the average,
    // it's a good candidate for filling to keep the mean residual tight.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We penalize very small residuals (dead space < 5) unless it's the end of the stream.
    let mut score = post;

    if post < 5.0 && post > 0.0 {
        score += 20.0 * (1.0 - progress);
    }

    // Non-linear coupling: Favor bins that align with the lookahead item.
    // If the next item fits into the post_residual, we reward this bin significantly.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.8;
    }

    // Pressure management: If we are late in the stream, favor closing bins (lower post_residual).
    // If early, allow more flexibility to keep bins open for future packing.
    if progress < 0.7 {
        score += (mean_residual - post) * 0.2;
    }

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // New bin penalty scales with how well the item fits into existing bins.
        // We make it harder to open a new bin if many bins are already open.
        score = 45.0 + (open_bins_count as f64 * 0.5) - (progress * 10.0);
    }

    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We use a quadratic penalty on post_residual to discourage leaving large empty gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Class Logic: Reward placements that result in 'round' residuals 
    // (e.g., multiples of 10 or 25), as they are more likely to fit future items.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 20.0;
    }

    // 3. Lookahead Synergy: If next_item_size is known, reward bins that leave 
    // exactly enough space for it (or slightly more).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            score -= 40.0;
        } else if post_residual < next_item_size {
            // Severe penalty if we create a gap that can't fit the next item
            score += 25.0;
        }
    }

    // 4. Scarcity/Open Bin Pressure: If fitting_bins_count is 1, it's our last chance.
    // If it's a new bin (bin_residual == bin_capacity), penalize based on open_bins_count.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few open bins.
        score += (open_bins_count as f64) * 12.0;
        // Moderate penalty based on progress to avoid opening new bins late in the stream.
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else if fitting_bins_count == 1 {
        // Reward using the last available bin to prevent unnecessary new bin creation.
        score -= 30.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate too far from the current mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
