    // Final adjustment: prioritize bins that are nearly full towards the end of the stream
    // to minimize the number of active bins.
    score -= (bin_capacity - post_residual) as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "fragment" (small sliver of space that is hard to fill)
    // We penalize post_residual ranges that are likely to be unusable (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size fits in this post_residual, reward this bin choice
    if next_item_size > 0 && next_item_size <= post_residual {
