    }

    // Harmonic class logic: prioritize filling bins to specific thresholds (e.g., 1/2, 1/3 of capacity)
    // This reduces the number of "half-empty" bins by forcing tighter packing towards 100
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.75 {
        score -= 20.0;
    }

    // If this is the only bin that can fit the item, we are forced to pick it.
    // However, if the fit is very poor (large post_residual), we might prefer a new bin.
    if fitting_bins_count == 1 && post_residual > 50 {
