    }

    // New bin logic: if bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize opening a new bin based on how many empty/underutilized bins we have.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.2);
    }

    // Progress awareness: as we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
