    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the remaining capacity.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Fragmentation Control: Discourage creating bins with very small, 
    // unusable residuals (e.g., 1-9) unless it's the end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0 * (1.0 - progress);
    }

    // 4. Global Density Awareness: If we have many open bins, penalize 
    // opening new ones unless the fit is perfect.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If it's a new bin, reward if it's the only way to fit the current item
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // 5. Dynamic Thresholding: As the stream nears completion, 
    // become more aggressive about filling existing bins to minimize total count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 6. Mean Residual Balancing: If this bin's post_residual is significantly 
    // lower than the global average, it's a good candidate to keep balanced.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    // Minimize post_residual to pack tightly.
    let mut score = post_res;

    // Penalty for creating "dead space" (small residuals that are unlikely to fit future items).
    // We penalize values below 10 (as minimum item size is likely around 10).
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this bin.
    // We apply this reward exponentially as we get deeper into the stream.
    if next_item_size > 0 && post_res >= next_item_size as f64 {
        score -= (1.0 + progress) * (post_res - next_item_size as f64);
    }

    // New Bin Penalty: If this is an empty bin, penalize it based on how many bins are already open.
    // We only want to open a new bin if the existing fits are extremely poor.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // Global load balancing: If the current bin's residual is significantly lower than the mean_residual,
    // it suggests we are filling this bin "too well" compared to others, potentially stranding items.
    // We slightly penalize bins that are much tighter than the average to encourage even distribution.
    if post_res < mean_residual {
        score += (mean_residual - post_res) * 0.5;
    }

    // Final scaling: favor bins that are the "last chance" (fitting_bins_count == 1) 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable gaps.
    // Gaps < 10 are often "dead space" as items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If the next item is large, prioritize keeping larger residuals.
    // If next_item_size is large, a small post_residual is a massive penalty.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the existing fit is poor.
    // If this is a new bin (residual == capacity), we set a high baseline cost.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (tight packing)
        // or if we have very few bins open.
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // 4. Harmonic Alignment: Reward fitting items into bins that align with the capacity.
        // Bins with residuals divisible by 10 or 25 are often easier to fill later.
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual % 25 == 0 {
            score -= 10.0;
        }
    }

    // 5. Progression Scaling: As we reach the end of the stream, prioritize space utilization.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.1);

    // 6. Scarcity Penalty: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it's too small to fit typical future items
    // If post_residual is in (0, 10), it's highly likely to be wasted (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the resulting gap, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 5 {
            score -= 30.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if we have many bins already open.
    // This penalizes the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly above the mean, 
    // it suggests this bin is "emptier" than others; prioritize filling it to keep the mean low.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
