        score -= (100.0 - diff) * 0.5;
    }

    // 3. Penalize opening new bins unless necessary
    // If it's a new bin (bin_residual == bin_capacity), add a heavy penalty
    if bin_residual == bin_capacity {
        score += 45.0; 
