        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 4. Tightness objective: Favor bins that stay near the mean_residual
    // This helps maintain a uniform distribution of fill levels
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression adjustment: As the stream nears the end, become more aggressive
    // about filling existing bins to reduce the total count
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
