pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // Logic: 
    // 1. Prioritize Best-Fit (minimize post_residual).
    // 2. Penalize opening a new bin unless the current best fit is "too tight" (leaves < 5 space) 
    //    and the next item is large, or if the mean residual is already high.
    // 3. Incorporate global state to resist opening new bins as the stream nears completion.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space. Lower is better (Best Fit).
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin based on how many options we currently have.
        // If we have many options, opening a new bin is inefficient.
        score += (fitting_bins_count as f64) * 15.0;

        // As we reach the end of the stream, penalize opening new bins heavily.
        score += (progress * 50.0);
    } else {
        // If it's an existing bin, favor bins that keep the mean residual balanced.
        // This encourages leveling out the bin usage.
        score += (post_residual as f64 - mean_residual).abs() * 0.5;

        // Lookahead: If the next item is large and this bin can't fit it, 
        // we might prefer to leave this space for a smaller item.
        if next_item_size > post_residual && next_item_size > 50 {
            score += 10.0;
        }
    }

    // Secondary penalty for leaving "dead space" (small fragments that are hard to fill).
    // Specifically, residuals between 1 and 9 are often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize post_residual (Best Fit), but penalize small residuals 
    // that are too small to fit common future items (Dead Space Penalty).
    // We use a non-linear penalty for residuals in the (0, 10) range (effectively unusable space).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead coupling: If a known next item is large, penalize placing the current item 
    // in a bin that would leave too little room for it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Global state weighting: Favor filling bins early in the stream (low progress)
    // and consolidate as we approach the end of the stream.
    let consolidation_pressure = (1.0 - progress) * (open_bins_count as f64 * 0.5);

    // New bin bias: If this is a new bin (post == bin_capacity), calculate the cost
    // of starting a new bin vs filling existing ones.
    let score = if bin_residual == bin_capacity {
        // High base cost for opening a new bin, reduced by the need to preserve 
        // capacity for future items if existing bins are already highly fragmented.
        50.0 + (mean_residual * 0.2) - (progress * 10.0)
    } else {
        post + dead_space_penalty + lookahead_penalty + consolidation_pressure
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post_residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Harmonic Penalty: Penalize residuals that are not multiples of common item sizes (10, 20, 25)
    // to keep space "usable" for future items.
    let harmonic_waste = (post_residual % 10) as f64 * 1.5;
    score += harmonic_waste;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // New Bin Logic: Only open a new bin if the current fit is extremely poor (large residual)
    // or if we are forced to (fitting_bins_count == 0).
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = -100.0; // Forced to open new
        } else {
            // Heavily penalize opening a new bin prematurely to force Best Fit
            score = 150.0 + (progress * 50.0);
        }
    } else {
        // Encourage filling bins that are already "fuller" than the mean to consolidate space
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 10.0;
        }

        // Final thresholding: If post_residual is very small (perfect fit), reward it
        if post_residual < 5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #952: Strict Best-Fit with Lookahead and Dead-Space Penalization.
    // Objectives:
