    if fitting_bins_count == 1 && post_res > 0.0 {
        score -= (1.0 - progress) * 20.0;
    }

    // Penalize opening a new bin (bin_residual == bin_capacity) 
    // unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 15.0);
    }

    // Balance the mean residual: discourage bins that deviate significantly from the 
