    // If we have a next_item_size, we want to ensure the post_residual can accommodate it.
    // If post_residual is smaller than the next item, we penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // 4. Thresholding for New Bins:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We only open a new bin if the current open bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the mean residual is already quite low,
        // or if we have very few open bins (avoid fragmenting early).
        if open_bins_count > 0 {
            score += 25.0 + (mean_residual * 0.5);
        }
    }

    // 5. Fitting Constraint:
    // If this is the only bin that can fit the item, we heavily discount it 
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progressive packing:
    // As we reach the end of the stream, we become more aggressive in filling bins (lower scores).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
