    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Discourage new bin if items are still arriving
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // 4. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Global Efficiency: Penalize placements that deviate significantly from the current mean residual.
    // This promotes filling bins somewhat uniformly to avoid "orphan" bins with high residuals.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Lookahead mechanism: If the post_residual perfectly fits the next item, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. Avoid opening new bins prematurely:
    // If this is a brand new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 65.0;
    }

    // 4. Tighten packing as the stream progresses:
    // Toward the end of the stream, prioritize closing bins (lower residuals)
    // by penalizing bins that remain significantly above the mean residual.
    let progress = step_index as f64 / total_items as f64;
    if post_residual as f64 > mean_residual {
        score += progress * 15.0;
    }

    // 5. Critical Thresholding:
    // If a bin has very little space left, it is "dying". If it cannot fit the next item,
    // we want to prioritize it to "finish it off" before it becomes useless.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 20.0;
    }

    // 6. Prefer bins that keep the overall average residual low
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating small, unusable gaps (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Best-Fit Decreasing behavior: prefer smaller post_residual
    // But penalize opening a new bin if an existing bin is a good fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if others can fit the item
            score += 120.0 + (progress * 50.0);
        } else {
            // Baseline cost for a new bin
            score = 40.0;
        }
    } else {
        // Reward bins that maintain a high mean_residual (keep bins "fresh")
        // or penalize if this placement drags the mean too low
        if (post_residual as f64) < mean_residual * 0.8 {
            score += 15.0;
        }
    }

    // Lookahead: If next item is large, favor keeping space open for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize filling a bin that would have been a perfect fit for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else if post_residual >= next_item_size && post_residual < (next_item_size + 10) {
            // Reward bins that can accommodate the next item comfortably
            score -= 20.0;
        }
    }

    // Dynamic pressure: As we near the end, be more aggressive with packing
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill)
    // We penalize residuals in the 1-9 range heavily as they are unusable for the given constraints.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 15.0;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, favor bins where the post_residual is sufficient to hold it.
    // This effectively implements a Best-Fit-Decreasing style lookahead.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Progress-sensitive scaling:
    // As the stream nears completion, become more aggressive about minimizing open bins.
    // Penalize opening new bins (where res == cap) more heavily as progress increases.
    if res == cap {
        score += 25.0 * (1.0 + progress);
    }

    // Global state optimization:
    // Favor bins that align with the current average residual to keep bin states uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    // Constraint: If this is the only bin that can fit the item, reward it to prevent
    // premature opening of new bins.
    if fitting_bins_count == 1 && res != cap {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1016: Harmonic-Residual Balancing
    // We prioritize bins that create "high-probability" residuals for future items.
    // A residual is "harmonic" if it is a multiple of common item sizes or near-zero.

    let mut score = post_residual as f64;

    // 1. Penalty for leaving "dead-zone" residuals (too small for most items, too large for efficiency).
    // Specifically, residuals between 1 and 9 are often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping the bin useful for the next item
            score -= 15.0;
        } else {
            // Penalty for stranding the next item if this bin was our best candidate
            score += 10.0;
        }
    }

    // 3. Harmonic alignment: Favor residuals that are multiples of 20 (common in many distributions).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 4. Density control: Avoid opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score -= 10.0; // Essential new bin
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, tighten constraints to prevent fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 6. Mean residual feedback:
    // If this bin's post_residual is significantly worse than the current mean, penalize.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

