    // average efficiency of open bins to keep bin states synchronized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current 
    // fit is objectively poor (e.g., leaving a large, unusable gap).
    if bin_residual == bin_capacity {
        // This is a new bin. Only pick if existing bins have very poor fits.
        // We set a threshold based on the average residual.
        score = mean_residual * 0.8;
    } else {
        // If this is the only bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive 
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
