    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post;

    // Penalty for creating "dead space" (very small residuals that are hard to fill)
    // We penalize post_residuals that are non-zero but smaller than the minimum possible item size (10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If the next item cannot fit into the current post_residual,
    // we penalize this bin to encourage saving space for the next item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic adaptation: As the stream progresses, favor packing tighter (lower residuals)
    // to avoid leaving fragmented bins near the end of the stream.
    score += (post * progress * 0.5);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // fitting bins are available. If we have many options, opening a new bin is expensive.
    if bin_residual == bin_capacity {
        score += 40.0 + (fitting_bins_count as f64 * 10.0);
    }

    // Influence of current bin state: penalize bins that deviate significantly from the mean
    // to keep bin levels balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (residuals too small for common items)
    // Small residuals (1-9) are highly undesirable as they rarely fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward fitting the next item (Lookahead synergy)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic/Modulo logic: prioritize bins that leave "clean" remainders (multiples of 10)
    // as they provide better flexibility for varying item sizes.
    if post_residual % 10 == 0 {
        score -= 15.0;
    }

    // If this is the last chance to fit the item in an existing bin, favor it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless the residual of existing bins is very poor (Best-Fit principle).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, penalize opening another one significantly.
        score += (open_bins_count as f64) * 2.0;
    }

    // Scaling by progress: as the stream nears the end, prioritize packing tightly over flexibility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // Prefer bins that are already closer to being full (Best-Fit behavior).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead space" gaps (1-9) 
    // that are unlikely to fit future items. Balance against open_bins_count to reduce fragmentation.

    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Base Score: Preference for tighter fits (Best-Fit principle).
    let mut score = post_res;

    // 2. Dead Space Penalty: If the resulting gap is too small to fit the smallest possible 
    // common items (10), we penalize it heavily unless it closes the bin perfectly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_res) * 5.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, 
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Global Pressure: As we progress through the stream, penalize opening new bins 
    // if there are existing bins that can accommodate the item.
    if is_new_bin {
        // If other bins can fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin fits, this is a necessary expense.
            score -= 10.0;
        }
    } else {
        // Encourage filling existing bins that are already "half-full" to keep mean_residual balanced.
        if (bin_capacity - bin_residual) > (bin_capacity / 2) {
            score -= 5.0;
        }
    }

    // 5. Fragmentation Control: Penalize high open_bins_count to encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The objective is to keep post_residual as small as possible (Best Fit),
    // but penalize creating "dead space" that cannot fit likely future items.

    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0).
    // If we are looking at a new bin (bin_residual == bin_capacity) and other bins could fit it,
    // apply a heavy penalty to force use of existing bins.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 2. Lookahead matching: If the post_residual is close to the next_item_size, 
    // it's a high-quality placement. Reward this match.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.5;
        } else {
            // Penalize creating a hole that is too small for the next item
            score += 50.0;
        }
    }

    // 3. Fragmentation control: Penalize creating residuals smaller than the smallest likely item (10)
    // unless it is exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global balance: If the current bin's residual is significantly worse than the 
    // mean residual of all open bins, penalize it to encourage balancing.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Progression awareness: As we approach the end of the stream, prioritize 
    // finishing bins (closing them) by rewarding smaller post_residuals more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. Lower score = better bin choice.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: The post-placement residual (Best Fit Decreasing principle).
    // We favor smaller post_residuals to keep bins tightly packed.
    let mut score = post_residual as f64;

    // 2. Penalty for opening new bins:
    // Only open a new bin if the current fit is extremely poor (high post_residual)
    // or if we are nearing the end of the stream.
    if is_new_bin {
        // High penalty for new bins to encourage filling existing ones.
        // Penalty decreases as the stream progresses (to clear out remaining items).
        score += 45.0 * (1.0 - progress);

        // If there are many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Logic:
    // If we have a next item, penalize bins that cannot fit the next item after this one.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a "dead zone" where the next item won't fit.
            score += 25.0;
        } else {
            // Reward bins that can accommodate the next item (Best Fit optimization).
            score -= 10.0;
        }
    }

    // 4. Global State Balancing:
    // If the mean residual is high, we are being too loose with bin usage.
    // Penalize bins that increase the mean residual further.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // 5. Critical Constraint:
    // If this is the ONLY bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

