    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (2.0 - progress);
    }

    // Lookahead logic: if next_item_size fits in the post_residual, reward this placement.
    // We scale this incentive by progress to be more aggressive as the stream ends.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * (1.0 + progress);
    }

    // Pressure to consolidate: penalize opening a new bin if other fitting bins exist.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the stream progresses (eventually we must open new bins).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 80.0 * (1.0 - progress);
