    // Mean-balancing: penalize bins that are significantly emptier than the average
    // to encourage filling existing "gaps" before creating new ones.
    let current_bin_fill = (bin_capacity - bin_residual) as f64;
    if current_bin_fill < mean_residual {
        score += (mean_residual - current_bin_fill) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
