    // 2. Lookahead: reward bins that can accommodate the next item perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Perfect match for next item
        } else if post_residual > next_item_size {
            // Reward bins that remain viable for the next item
            score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        } else {
            // Penalize bins that render the next item impossible to fit
            score += 25.0;
        }
    }

    // 3. Global balance: penalize creating bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation;

    // 4. Density incentive: favor filling bins that are already well-utilized
    let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * utilization;

    // 5. Progression scaling: as the stream nears the end, become more aggressive (Best Fit focus)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
