                score -= 30.0; // Perfect packing reward
            } else if gap_after_next < 10 {
                score += 15.0; // Penalty for creating a new small gap
            }
        }
    }

    // 4. New Bin Candidate logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is low.
    if bin_residual == bin_capacity {
        score += 40.0; // Base cost to open a new bin
        // If we are forced to open a new bin because existing ones are too fragmented, reduce penalty.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // 5. Global state normalization:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

