        score += 65.0;
        // Reduce cost if we have many open bins that are already very full (high mean_residual pressure).
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    }

    // 4. Fitting Pressure: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening an unnecessary new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression Scaling: As we reach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
