    // Edge case: If the bin is nearly full (residual < 10), it's often a "dead" bin.
    // Discourage placing items here if there are other open bins (unless it's a perfect fit).
    if post_residual < 10 && post_residual > 0 && open_bins_count > 1 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // Exponential growth for residuals < 15, as these are "dead zones".
    let fragmentation_penalty = if post < 15.0 {
        (15.0 - post).powf(2.5) * 5.0
    } else {
        0.0
    };

    // Lookahead: If next_item_size is large, favor bins that can accommodate it.
    // We penalize bins that would leave a post_residual too small for the next item.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 10.0
    } else {
        0.0
    };

    // Dynamic thresholding: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to reduce open_bins_count.
    let closure_incentive = if progress > 0.8 {
        (open_bins_count as f64) * -2.0
    } else {
        0.0
    };

    // Base score is the residual space. We want to minimize this (Best Fit).
    // We add penalties to avoid "near-empty" bin states.
    let mut score = post + fragmentation_penalty + lookahead_penalty + closure_incentive;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the item barely fits in anything else.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low or 
        // the current item size is very large relative to open bin capacities.
        let new_bin_base_cost = 45.0; 
        score += new_bin_base_cost - (fitting_bins_count as f64 * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize large post_residuals (dead space)
    // The lower the post_residual, the better the fit.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class logic: reward placements that leave residuals compatible with common item sizes
    // We penalize residuals that are "useless" (too small to fit common items like 10-20)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead integration: if a next item exists, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect" tandem fit (near zero residual after next item)
            let tandem_residual = post_residual - next_item_size;
            score -= (100.0 - tandem_residual as f64) * 0.5;
        } else {
            // Penalize if this bin will definitely not fit the next item
            score += 20.0;
        }
