    // 4. Global state pressure: if many bins are open, be more conservative about opening new ones
    // Penalize opening a new bin (bin_residual == bin_capacity) if we have many open bins
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 5. Mean residual equilibrium: avoid creating bins that deviate significantly from average
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Last chance heuristic: if this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
