        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item fits perfectly into this post_residual,
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. New Bin Thresholding: If this is an empty bin (new bin candidate),
    // only pick it if the mean residual of current bins is very low (indicating
    // all existing bins are nearly full and inefficient for the current item).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0;
        } else {
            score += 80.0;
        }
    }

    // 4. Scarcity/Pressure: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize filling the most empty bins to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += (bin_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
