    // Penalty for creating "dead space": 
    // We penalize small residuals that are too small to fit common items (e.g., < 10) 
    // unless it's a perfect fit (0).
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead coupling: 
    // If the next item is large, avoid leaving a residual that is just slightly too small 
