    // As the stream nears completion, become more aggressive in filling bins 
    // (reduce the penalty for opening new bins by lowering the relative cost of high residuals).
    // We dampen the impact of post_res as progress increases.
    score *= 1.0 - (0.2 * progress);

    // Open Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that decays as the stream progresses, but is modulated by the number of open bins.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 40.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0);
        score += new_bin_penalty;
    }

    // Fitting bins coupling:
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
