    // 2. If this is the only bin that fits the item, make it highly attractive to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 3. Lookahead integration: Penalize if the next item won't fit in the remaining space
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Global pressure: Penalize opening new bins as the stream progresses
    if bin_residual == bin_capacity {
        // Higher cost for new bins based on how many bins are already open
        score += 25.0 + (open_bins_count as f64 * 2.5);

        // As we reach the end of the stream, prioritize filling existing bins over opening new ones
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    // 5. Prefer bins that keep the mean residual closer to the item distribution average (heuristic balance)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

