    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // Penalty for leaving space that is too small for any likely item (dead space).
    if post_residual < 10 {
        score -= 20.0; // Reward tight packing
    }

    // 2. Lookahead synergy: if next item fits in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic classes: penalize residues that are "awkward" (cannot fit common item sizes).
    // If post_residual is in a range that is hard to fill (e.g., 1-9), penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Threshold for opening new bins: 
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the current fitting_bins_count is low or if current open bins are very full.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0; // Necessary to open
        } else {
            // Heavily penalize opening a new bin if existing bins have space
            score += 60.0 + (mean_residual * 0.5);
        }
    }

    // 5. Progression scaling:
    // As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit common items
    // If post_residual is > 0 and < 10, it's a "fragile" gap that effectively wastes space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead Coupling: If the next item exists, favor bins that can accommodate it
    // after placing the current item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that will definitely not fit the next item
            score += 20.0;
        } else {
            // Reward bins that have a "perfect" or "near-perfect" fit for the next item
            let remaining_after_next = post_residual - next_item_size;
            if remaining_after_next < 5 {
                score -= 10.0;
            }
        }
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: As the stream progresses, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are usually unusable for items 10+)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
