        // Further reward if it creates a tighter fit for the next item
        score -= (100.0 - (post_residual - next_item_size) as f64) * 0.1;
    }

    // 3. Penalty for opening a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fit is terrible elsewhere
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Mean-residual balancing: Avoid bins that deviate significantly from the average state
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency factor: If this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual >= item_size {
