pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bin creation early in the stream, but allow it if no other options exist.
    // The objective is to minimize post_residual (Best Fit), but we apply non-linear 
    // adjustments based on the potential to fit the next item (Lookahead).

    let mut score = post;

    // 1. Penalty for creating a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the progress so we become more selective as the stream ends.
    if bin_residual == bin_capacity {
        score += 45.0 + (35.0 * progress);
    }

    // 2. Lookahead interaction: if the next item is large, prioritize keeping larger residuals.
    // If the next item is small, prioritize tight packing (Best Fit).
    if next_item_size > 0 {
        let lookahead_diff = (next_item_size as f64 - post) / bin_capacity as f64;
        if lookahead_diff > 0.0 {
            // Penalize bins where the next item will not fit
            score += 20.0 * lookahead_diff;
        } else {
            // Reward bins that have just enough room for the next item
            score -= 15.0 * (1.0 - lookahead_diff.abs());
        }
    }

    // 3. Global density regularization:
    // If we have many open bins, penalize creating more by adding a cost proportional to open_bins_count.
    score += (open_bins_count as f64 * 0.5) * (1.0 + progress);

    // 4. Fitting constraint:
    // If this is the only bin that can fit the item, strongly prioritize it to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Smooth non-linear coupling with mean_residual to prevent "bin-starvation"
    // Keep the distribution of residuals somewhat uniform.
    let residual_imbalance = (post - mean_residual).abs() / bin_capacity as f64;
    score += 10.0 * residual_imbalance;

    score
}

