    if bin_residual == bin_capacity {
        // Only consider a new bin if we have many open bins already or if fitting_bins_count is 0.
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 5.0);
        } else {
            score -= 10.0; // Forced to open new bin
        }
    }

    // 4. Tightness Bias: Favor bins that become very full (Best Fit principle).
    // The smaller the post_residual, the better, provided it's not in the "dead space" trap.
    score += (post_residual as f64) * 0.5;

    // 5. Global Distribution Balancing: If the current bin residual is far below the mean,
    // we want to fill it up to avoid fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual represents space wasted.
