    // unless we have no other choice or the mean residual is already quite high.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, weighted by how many bins are already open
        score += 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If the bin is already open, favor it if its residual is close to the mean
        // to keep bin fullness levels balanced (Best-Fit principle).
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: If this is the only bin that can fit the item, 
    // aggressively prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
