    // 1. Best-Fit Penalty: Penalize large post_residuals (waste)
    // 2. Harmonic Class logic: Favor bins that leave small residuals or perfect fits (0)
    // 3. Lookahead Logic: If next_item_size can fit into the resulting post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if the residual after next_item_size is small (tight packing)
        if (post_residual - next_item_size) < 10 {
            score -= 30.0;
        }
    }

    // 4. Threshold for opening a new bin:
    // If we are forced to open a new bin (fitting_bins_count == 0), 
    // the residual is by definition 100 - item_size.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are all poor matches
        // Scale by open_bins_count to prevent runaway bin creation
        score += 20.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 5. Harmonic packing: penalize residuals that are small but not usable
        // (e.g., 1-9 is often dead space)
        if post_residual < 10 {
            score += 15.0; 
        }
    }

    // 6. Global density pressure: As we approach the end of the stream, 
    // be more aggressive in filling existing bins (lower scores for higher residuals)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // 7. Balance against mean_residual to prevent uneven bin wear
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it falls into the "unusable" range (1-9).
    // Items are >= 10, so any residual < 10 is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // reward this placement to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by how many bins are already available to fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin fits, this is forced; neutralize the penalty.
            score -= 10.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already "tight" (low residual) to keep 
    // empty bins available for larger items.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Progression scaling: As the stream nears the end, be more aggressive with packing
    // to avoid leaving single items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Primary Objective: Best Fit (Minimize post_residual)
    // We heavily penalize large gaps to avoid "stranded" space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Coupling:
    // If the next item can fit perfectly into the current post_residual, reward this bin.
    // We define a "perfect match" as post_residual being close to next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward placement that leaves exactly enough space for the next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 2.5;
        } else {
            // Penalize creating a bin that is too small for the predicted next item
            score += 50.0;
        }
    }

    // 3. Global State Awareness:
    // If this is the only fitting bin, prioritize it to keep bin count low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 4. Thresholding New Bins:
    // If evaluating an empty bin (bin_residual == bin_capacity), apply a penalty
    // based on how many bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 300.0;
        }
    }

    // 5. Normalization against mean_residual:
    // Encourage bins to stay near the average residual to maintain uniformity.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // 1. Base cost is the post_residual (Best Fit approach).
    let mut score = post_residual as f64;

    // 2. Penalize opening a new bin if other bins can accommodate the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead heuristic: If a future item exists, penalize bins that leave behind
    //    a residual that is too small for common item sizes, or prioritize bins 
    //    that leave space exactly matching the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // Perfect future alignment
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // Fragmentation penalty
        }
    }

    // 4. Global state pressure: If we are deep into the stream, become more aggressive 
    //    with Best Fit to minimize open bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Balance the mean residual: Avoid creating bins that are significantly 
    //    worse than the average current bin.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    // 6. Penalty for creating very small, unusable residuals ("slivers").
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: proportional to the progress (later in the stream, 
    // we are more desperate to avoid new bins).
    if is_new_bin {
        score += 80.0 * (1.0 + progress);
    }

    // Heuristic: Penalize leaving "dead space" that is too small for common items.
    // As the stream progresses, our tolerance for dead space decreases.
    let penalty_factor = 2.5 * (1.0 - progress);
    if post_residual > 0 && post_residual < 20 {
        score += penalty_factor * (20.0 - post_residual as f64);
    }

    // Lookahead logic: If the next item is large and the current post_residual 
    // makes it impossible to fit, add a penalty.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 * (1.0 - progress);
    }

    // Coupling with mean_residual: If this bin's post_residual is significantly 
    // lower than the average residual, we reward it to encourage packing consistency.
    if !is_new_bin {
        let deviation = mean_residual - post_residual as f64;
        score -= 5.0 * deviation.tanh();
    }

    // If this is the last chance for the item to fit in existing bins, 
    // heavily penalize opening a new bin by reducing the score of valid bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Class Penalty: Penalize residuals that are small but unusable 
    // for standard item ranges. If post_residual is < 10, it is likely "dead space".
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If next_item_size can fit into the remaining space, 
    // reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the 
    // current one more aggressively (Best-Fit principle).
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * 0.5;
    }

    // 4. Modulo Alignment: Favor residuals that are multiples of 20, 
    // as they are more likely to accommodate common item sizes.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin (bin_residual == bin_capacity)
    // unless the current average residual is already quite low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 20.0;
        } else {
            score += 60.0;
        }
    }

    // 6. Progressive Tightening: As the stream nears completion, 
    // become more conservative about wasting space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict dead space avoidance (Best Fit Decreasing logic)
