    // We penalize larger residuals quadratically to prefer tighter packing.
    let mut score = post * post * 0.01;

    // Penalty for opening a new bin: if this is a new bin, apply a threshold cost
    // that scales with the progression of the stream (early on, we are more conservative).
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 25.0);
