        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: If the next item is large and won't fit in this tight bin, 
    // penalize this placement to keep the bin open for the next item.
    if next_item_size > 0 && (post as u32) < next_item_size {
        score += 15.0 * (1.0 - progress);
    }

    // Encourage using existing bins over opening new ones as the stream progresses.
    // If this is a new bin (bin_residual == bin_capacity), apply a progress-dependent cost.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins, decreasing slightly as we reach the end
        // to allow for cleanup, but generally keeping the bin count low.
        score += 45.0 * (1.0 - 0.2 * progress);
    }

    // If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Interaction with mean_residual: If we are creating a bin that is much emptier 
    // than the average, we are likely fragmenting space.
    if (post as f64) > mean_residual {
        score += 5.0 * (post / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a "sliver" of space (dead space 1-9) that is unlikely to be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: Prefer bins that leave space matching the next_item_size (lookahead synergy).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        score += diff as f64 * 0.4;
    }

    // Harmonic logic: Favor bins that leave room for common integer divisions of capacity.
    // We want to keep the residual as a multiple of 20 or 25 to maximize future flexibility.
    let remainder = post_residual % 20;
    score += (remainder as f64).powf(1.1);

    // If this is the only bin that fits, we are forced to take it. 
    // Heavily incentivize this to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin unless the current available bins are very full (low mean_residual).
    if bin_residual == bin_capacity {
        score += 60.0;
        if mean_residual > 30.0 {
            score += 40.0;
        }
    }

    // Bias towards filling the most empty bin first to keep residuals balanced (Best Fit logic).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
