        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.5;
    }

    // 5. Last Chance Logic: If this is the only bin that fits, heavily favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
