    // Favor opening a new bin only if existing bins are very tight (high fitting_bins_count vs open_bins_count)
    // and we are late in the stream where packing efficiency matters less than completion speed.
    let new_bin_bias = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Penalize new bin creation based on current fragmentation
            let density_factor = (open_bins_count as f64) / (step_index as f64 + 1.0);
            (100.0 - mean_residual) * (1.0 + progress) * density_factor
        }
    } else {
        0.0
    };

    // Non-linear coupling: Exponentially penalize post_residual as it approaches 0 (Best-Fit)
    // but modulate by stream progress to allow more slack early on.
    let fit_score = (post * post) / (1.0 + progress * 0.5);

    fit_score + lookahead_penalty + uniformity_bonus + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space (small residuals < 10 are often wasted)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if next_item_size fits in the post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // Encourage filling bins to capacity (Best-Fit principle)
    // Reward lower post_residual values
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Harmonic class logic: identify bins that are nearly full to prioritize them
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 15.0;
    }

    // Penalty for opening new bins if alternatives exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score += 5.0;
        }
    }

    // Adaptive smoothing based on progress
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: be more aggressive about filling existing bins
        score -= (open_bins_count as f64) * 0.5;
    }

    // Reward bins that bring the post_residual into "harmonic" sizes (multiples of 20)
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit typical items (e.g., < 10)
    // but large enough to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the current
    // residual, reward this bin placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = (post_residual - next_item_size) as f64;
        if gap_after_next == 0.0 {
            score -= 40.0; // Perfect fit potential
        } else if gap_after_next < 10.0 {
            score -= 15.0; // Good fit potential
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Necessary new bin
        }
    }

    // 4. Density Balancing: Favor bins that keep the mean_residual aligned with item_size
    // to prevent fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression Weighting: As we approach the end of the stream, prioritize 
    // filling current bins to clear out open bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
