    let mut score = post;

    // Penalty for creating a "fragment" (very small, unusable residual space)
    // We penalize small residuals more heavily as the stream progresses to consolidate bins.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: If the next item could fit in this bin, prioritize this bin.
    // If the next item cannot fit, penalize this bin to save space for larger items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post) * 0.3;
        }
