    // Dynamic constraint: If this is the only bin that fits the item (fitting_bins_count == 1),
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Global state awareness: If we have many open bins, prioritize closing them (lower post_residual)
    // If we have few open bins, allow slightly more fragmentation to keep the stream moving.
    score += (open_bins_count as f64) * (post / bin_capacity as f64);

    // Bias against opening a new bin (where bin_residual == bin_capacity)
    // This bias increases as the stream progresses to prevent fragmentation at the end.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
