    // 4. Tightness Reward: Favor bins that become very full (Best-Fit principle).
    // As post_residual approaches 0, decrease the score significantly.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. Distribution Awareness: Penalize significantly above-average residuals.
    if (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
