    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // 5. New Bin Thresholding: 
    // If bin_residual == bin_capacity, it's a new bin. 
    // We only open a new bin if the score is significantly better than existing options.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are very full (low mean_residual).
        score += 35.0 + (mean_residual * 0.2);
    }

    // 6. Global progression adjustment:
    // As the stream nears completion, become more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

