            score += 15.0 * (1.0 - (post_res / next_item));
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower residual) 
    // more aggressively to reduce the total count of open bins.
    let consolidation_factor = 10.0 * progress;
    score += consolidation_factor * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold penalty.
    // Only open a new bin if the existing bins are extremely poor fits.
    if bin_residual == bin_capacity {
        // Penalty is high, but decreases as we have fewer fitting options.
        // If fitting_bins_count is 0, we MUST open a new bin (score becomes 0 or negative).
        score = 45.0 - (fitting_bins_count as f64 * 10.0);
    } else {
