    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If a future item exists, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit both current and next item
            score -= 25.0;
        } else {
            // Penalize if the current placement prevents the next item from fitting
            score += 15.0;
        }
    }

    // 3. Dynamic Thresholding based on progress
    // As the stream progresses, prioritize closing bins (Best Fit) to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    // 4. Global State Awareness
    // Discourage opening a new bin if other bins are still quite empty.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is proportional to the average emptiness of current bins.
        score += mean_residual * 0.5;

        // Only open a new bin if we have no other options or if it's highly efficient.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Prefer tighter fits (Best Fit heuristic)
    // The base score (post_residual) already favors smaller remainders.
    // We enhance this by penalizing bins that are too empty compared to the global mean.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

