    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for next item reduces score (reward)
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Cannot fit next item, penalize proportionally to how much space is left
            score += post_residual as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if fitting_bins is 0.
        // Penalty for opening a new bin is high to encourage packing into existing bins.
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // Urgent need to open
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly from average density
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression Weight: As we near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}
